insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m1-l1', 'liderar-el-proceso-comercial', 'Liderar el proceso comercial', 'Por qué la persona que vende es quien debe marcar el ritmo de la conversación.', 'mentalidad', 1, 4, '["Cuando una oportunidad comercial se estanca, es habitual pensar que la solución es esperar. Esperar a que la otra persona escriba, a que revise la propuesta, a que tenga un momento. Esa espera, sostenida en el tiempo, es la principal causa de que las oportunidades se enfríen.","Liderar el proceso comercial significa asumir que a vos te corresponde proponer el próximo paso. No se trata de apurar una decisión, sino de facilitarla: dar la información que falta, proponer una fecha, ofrecer un recurso concreto.","Una persona que lidera su proceso comercial no depende del estado de ánimo o la agenda del cliente para avanzar. Define de antemano qué acción va a tomar si no recibe respuesta, y la ejecuta con calma.","Esto no tiene relación con la insistencia. Insistir es repetir lo mismo esperando un resultado distinto. Liderar es aportar algo nuevo en cada intervención para que la persona tenga motivos reales para responder."]'::jsonb, array['liderar', 'proceso comercial', 'proactividad', 'mentalidad'], array['m1-l2', 'm1-l3', 'm2-l3'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m1-l2', 'accionar-sin-perseguir', 'Accionar sin perseguir', 'La diferencia entre tomar acción con criterio y perseguir a un potencial cliente.', 'mentalidad', 2, 3, '["Perseguir es enviar el mismo mensaje con distintas palabras, cada vez con más frecuencia y menos contenido. Accionar con criterio es distinto: cada contacto tiene un propósito claro y aporta algo que la conversación anterior no tenía.","Potentia parte de una premisa simple: no hace falta presionar para liderar. Alcanza con ser consistente, aportar valor en cada mensaje y respetar los tiempos de la otra persona sin abandonar el seguimiento.","Accionar con criterio también implica saber cuándo detenerse. Un proceso comercial saludable tiene un principio y un final, aunque ese final sea ''sigamos en contacto más adelante''."]'::jsonb, array['perseguir', 'accionar', 'criterio', 'presión'], array['m1-l1', 'm1-l4', 'm4-l11'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m1-l3', 'el-cliente-no-es-responsable', 'El cliente no es responsable de hacer avanzar la venta', 'Por qué esperar que la otra parte tome la iniciativa suele frenar la oportunidad.', 'mentalidad', 3, 3, '["Es común escuchar frases como ''si le interesa, que escriba''. Esa idea suena razonable, pero desconoce cómo funciona realmente la toma de decisiones: las personas postergan lo que no es urgente, incluso cuando les interesa.","El potencial cliente no tiene la misma información que vos sobre el proceso, los tiempos ni los próximos pasos posibles. Por eso, hacer avanzar la conversación es una responsabilidad compartida en la que quien vende tiene más herramientas.","Esto no significa cargar con la decisión final de la otra persona. Significa quitar fricción: proponer fechas, resumir lo conversado, aclarar dudas antes de que se conviertan en excusas para no responder."]'::jsonb, array['responsabilidad', 'iniciativa', 'avance'], array['m1-l1', 'm2-l3'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m1-l4', 'esperar-insistir-acompanar', 'Diferencia entre esperar, insistir y acompañar', 'Tres formas de vincularse con una oportunidad y por qué solo una funciona a largo plazo.', 'mentalidad', 4, 4, '["Esperar es no actuar: dejar que el tiempo pase confiando en que la otra persona retome el contacto por su cuenta. Suele derivar en oportunidades que se enfrían sin que nadie lo decida explícitamente.","Insistir es actuar sin criterio: repetir el mismo pedido, aumentar la frecuencia de los mensajes y transmitir urgencia. Genera el efecto contrario al buscado: la persona se aleja o deja de responder por completo.","Acompañar es la tercera vía, y es la que propone Potentia. Acompañar significa mantenerse presente de forma útil, con una cadencia razonable, aportando algo distinto en cada contacto y respetando que la decisión final no es tuya.","El Sistema 4x4, que vas a ver en el módulo correspondiente, es una forma estructurada de acompañar sin caer en la espera pasiva ni en la insistencia."]'::jsonb, array['esperar', 'insistir', 'acompañar', 'seguimiento'], array['m1-l2', 'm4-l9'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m1-l5', 'la-claridad-como-herramienta', 'La claridad como herramienta comercial', 'Por qué un mensaje claro convierte más que uno persuasivo.', 'mentalidad', 5, 3, '["Muchas conversaciones comerciales se estancan no porque el cliente no esté interesado, sino porque no está claro qué se espera de él. Un mensaje que termina en ''quedo atento'' no propone nada concreto.","La claridad reduce la carga mental de la otra persona: le dice exactamente qué se necesita, en qué plazo y qué pasa después. Cuanto más simple es la acción pedida, más fácil es que ocurra.","Aportar claridad no es lo mismo que apurar. Se puede ser claro y, al mismo tiempo, dejar margen para que la persona decida cuándo y cómo continuar."]'::jsonb, array['claridad', 'comunicación', 'mensajes'], array['m4-l5', 'm4-l6'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m2-l1', 'que-es-un-proceso-comercial', 'Qué es un proceso comercial', 'Una definición simple para ordenar cualquier oportunidad, sin importar el rubro.', 'proceso-comercial', 1, 3, '["Un proceso comercial es la secuencia de pasos que recorre una persona desde que manifiesta interés hasta que toma una decisión. Puede ser breve (una consulta y una respuesta) o extenso (varias reuniones y una propuesta formal).","Da igual si vendés un servicio, un producto o una asesoría: siempre hay un punto de partida, momentos de intercambio de información y un punto de decisión. Nombrar esas etapas ayuda a entender en qué lugar está cada oportunidad.","Potentia no pide registrar un pipeline completo. Alcanza con reconocer, para cada oportunidad activa, en qué etapa general se encuentra y cuál sería el próximo paso razonable."]'::jsonb, array['proceso comercial', 'definición', 'etapas'], array['m2-l2', 'm2-l5'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m2-l2', 'etapas-de-una-oportunidad', 'Etapas de una oportunidad', 'Un mapa simple de las instancias más frecuentes en un proceso comercial de servicios.', 'proceso-comercial', 2, 4, '["Aunque cada negocio tiene particularidades, la mayoría de las oportunidades de servicios atraviesan momentos similares: primer contacto, conversación exploratoria, presentación de una propuesta y una instancia de decisión.","Entre esos momentos suele haber zonas grises: reuniones que se coordinan y no se concretan, propuestas que se envían y no se responden, decisiones que dependen de terceros. Identificar en qué zona gris está una oportunidad es clave para saber qué acción tomar.","En la sección Accionar, Potentia te pide ubicar tu oportunidad dentro de estas etapas para sugerir una acción específica en lugar de una recomendación genérica."]'::jsonb, array['etapas', 'oportunidad', 'reunión', 'propuesta'], array['m2-l1', 'm2-l3'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m2-l3', 'definir-proximos-pasos', 'La importancia de definir próximos pasos', 'El hábito que más impacto tiene en la velocidad de una oportunidad.', 'proceso-comercial', 3, 3, '["Terminar una conversación sin acordar un próximo paso concreto es una de las causas más frecuentes de estancamiento. ''Quedamos en contacto'' no es un próximo paso: es una despedida ambigua.","Un buen próximo paso tiene tres características: está definido en el tiempo, tiene un responsable claro y es lo suficientemente pequeño como para ejecutarse sin fricción.","Ejemplos de próximos pasos concretos: ''te escribo el jueves con la propuesta'', ''coordinamos una llamada de 15 minutos el martes'', ''me confirmás antes del viernes si avanzamos''."]'::jsonb, array['próximo paso', 'cierre de reunión', 'seguimiento'], array['m1-l3', 'm2-l4'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m2-l4', 'evitar-conversaciones-abiertas', 'Cómo evitar conversaciones comerciales abiertas', 'Señales de que una oportunidad quedó sin rumbo y cómo cerrarla o reactivarla.', 'proceso-comercial', 4, 3, '["Una conversación comercial queda abierta cuando nadie propuso un cierre ni un próximo paso, y el tiempo empieza a pasar sin que nadie lo note. Con frecuencia, esto ocurre después de compartir una propuesta o cotización.","La señal más clara es la ausencia de fecha: si no hay una fecha (propia o del cliente) asociada a la oportunidad, es momento de proponer una.","Cerrar una conversación abierta no significa forzar una respuesta. Significa proponer explícitamente qué sigue, incluso si esa propuesta es ''retomemos en tres semanas''."]'::jsonb, array['conversación abierta', 'estancamiento', 'cierre'], array['m2-l3', 'm4-l10'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m2-l5', 'que-significa-convertir-una-oportunidad', 'Qué significa convertir una oportunidad', 'Ir más allá del ''sí'' o el ''no'' para entender qué es realmente una conversión.', 'proceso-comercial', 5, 3, '["Convertir una oportunidad no siempre significa cerrar una venta de inmediato. En muchos procesos, convertir significa lograr que la persona avance a la siguiente etapa: agendar una reunión, aceptar recibir una propuesta, confirmar una fecha de decisión.","Pensar la conversión en etapas intermedias ayuda a mantener la motivación y a medir el proceso comercial de forma más realista que esperando solamente el cierre final.","Cada mensaje que enviás en un seguimiento debería tener en mente cuál es la próxima micro-conversión que buscás, no solo el resultado final."]'::jsonb, array['conversión', 'cierre', 'resultado'], array['m2-l1'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m3-l1', 'para-que-sirve-un-crm', 'Para qué sirve un CRM', 'Qué resuelve un CRM y por qué Potentia no reemplaza esa función.', 'organizacion-comercial', 1, 3, '["Un CRM (Customer Relationship Management) es una herramienta pensada para registrar contactos, oportunidades, historiales de conversación y tareas comerciales a lo largo del tiempo, generalmente en equipos con varios vendedores.","Potentia no cumple esa función y no busca hacerlo. Potentia no guarda tus oportunidades, no registra contactos ni conserva historial de conversaciones: te ayuda a decidir qué hacer en el momento en que lo necesitás.","Si gestionás muchas oportunidades en simultáneo, con varias personas involucradas, probablemente necesites un CRM además de aplicar los criterios que aprendés en Potentia."]'::jsonb, array['CRM', 'organización', 'gestión de oportunidades'], array['m3-l2'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m3-l2', 'cuando-alcanza-con-una-planilla', 'Cuándo alcanza con una planilla', 'Señales de que todavía no necesitás una herramienta compleja de gestión.', 'organizacion-comercial', 2, 3, '["Si trabajás solo o sola, con un volumen moderado de oportunidades, una planilla simple suele ser suficiente para ordenar la información antes de necesitar un CRM.","Lo importante no es la herramienta, sino el hábito: revisar con regularidad en qué está cada oportunidad y qué acción corresponde. Eso puede hacerse en una planilla, una libreta o cualquier sistema que revises de forma consistente.","La complejidad de la herramienta debería crecer junto con la complejidad real del proceso, no antes."]'::jsonb, array['planilla', 'organización simple', 'CRM'], array['m3-l1', 'm3-l3'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m3-l3', 'informacion-minima-a-registrar', 'Qué información mínima conviene registrar', 'Los datos que hacen la diferencia a la hora de decidir una acción comercial.', 'organizacion-comercial', 3, 3, '["Independientemente de la herramienta que uses, hay datos mínimos que conviene tener a mano para cada oportunidad: fecha del último contacto útil, canal, etapa actual, y si existe una fecha acordada con la persona.","Con esos cuatro datos, la mayoría de las decisiones de seguimiento se vuelven mucho más simples, incluida la que te ayuda a tomar la sección Accionar de Potentia.","Evitá registrar información que no vas a usar. Cuanto más simple el registro, más probable que lo mantengas actualizado."]'::jsonb, array['información mínima', 'registro', 'seguimiento'], array['m3-l2', 'm3-l4'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m3-l4', 'lo-que-no-se-mide-no-se-mejora', 'Lo que no se mide no se puede mejorar', 'Por qué revisar tus propios números comerciales, aunque sean simples, cambia resultados.', 'organizacion-comercial', 4, 3, '["No hace falta un dashboard sofisticado para empezar a medir. Alcanza con revisar, cada cierto tiempo, cuántas oportunidades tenés activas, cuántas avanzaron y cuántas se enfriaron.","Medir con criterio simple te permite detectar patrones: por ejemplo, si la mayoría de tus oportunidades se estancan después de enviar una propuesta, ahí hay algo para trabajar.","El objetivo no es acumular datos, sino tomar mejores decisiones con la información mínima necesaria."]'::jsonb, array['medición', 'indicadores', 'mejora'], array['m3-l3', 'm3-l5'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m3-l5', 'indicadores-comerciales-basicos', 'Indicadores comerciales básicos', 'Cuatro indicadores simples que cualquier profesional independiente puede seguir.', 'organizacion-comercial', 5, 4, '["Cantidad de oportunidades activas: cuántas conversaciones comerciales tenés abiertas en este momento.","Tasa de avance: de las oportunidades que tuvieron una primera conversación, cuántas llegaron a la etapa de propuesta.","Tiempo promedio de respuesta: cuánto tarda una persona, en promedio, en responder a tus mensajes de seguimiento.","Motivo de estancamiento más frecuente: si la mayoría de tus oportunidades frenan en el mismo punto (por ejemplo, después de la propuesta), ese es tu próximo foco de mejora."]'::jsonb, array['indicadores', 'métricas', 'conversión'], array['m3-l4'], true)
