insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m4-l1', 'que-es-el-sistema-4x4', 'Qué es el Sistema 4x4', 'La metodología de seguimiento central de Potentia, explicada de forma simple.', 'sistema-4x4', 1, 4, '["El Sistema 4x4 es una cadencia de seguimiento comercial compuesta por cuatro mensajes, enviados cada cuatro días hábiles, cuando ya existió una conversación previa o una manifestación de interés real.","Cada uno de los cuatro mensajes cumple una función distinta: retomar, aportar algo tangible, construir validación y cerrar el hilo con firmeza amable. No son cuatro variaciones del mismo mensaje.","El ciclo se detiene apenas la persona responde, sin importar en qué mensaje estés. El 4x4 no busca acumular contactos: busca facilitar una respuesta lo antes posible.","Es una herramienta de acompañamiento, no de presión. Su función es mantener viva una oportunidad real sin caer en la insistencia."]'::jsonb, array['sistema 4x4', 'seguimiento', 'metodología', 'cadencia'], array['m4-l2', 'm4-l4'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m4-l2', 'cuando-se-utiliza-el-4x4', 'Cuándo se utiliza', 'Las condiciones necesarias para aplicar el Sistema 4x4.', 'sistema-4x4', 2, 3, '["El 4x4 se utiliza cuando ya hubo una conversación previa o una manifestación de interés concreta: una consulta, una reunión, una respuesta a un mensaje anterior.","También es la herramienta indicada cuando se compartió una propuesta, cotización o información relevante y la persona dejó de responder.","Puede adaptarse cuando el cliente maneja un calendario formal de decisión (por ejemplo, procesos de compra corporativos), ajustando los tiempos a esos plazos en lugar de forzar los cuatro días hábiles."]'::jsonb, array['cuándo aplicar', 'condiciones', '4x4'], array['m4-l1', 'm4-l3'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m4-l3', 'cuando-no-se-utiliza-el-4x4', 'Cuándo no se utiliza', 'Los dos escenarios en los que el 4x4 no corresponde.', 'sistema-4x4', 3, 3, '["El 4x4 no se utiliza cuando el lead nunca respondió. Si nunca hubo una conversación, no hay un hilo que retomar: se trata de una instancia de contacto o reactivación, con otra lógica.","Tampoco se utiliza cuando ya existe una reunión agendada. En ese caso, lo que corresponde es una rutina de preparación o recordatorio, no una cadencia de seguimiento.","Aplicar el 4x4 fuera de estos casos genera mensajes forzados, que la otra persona percibe como plantillas genéricas en lugar de un acompañamiento real."]'::jsonb, array['cuándo no aplicar', '4x4', 'primer contacto', 'reunión agendada'], array['m4-l2'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m4-l4', 'como-funciona-la-cadencia', 'Cómo funciona la cadencia', 'El ritmo de cuatro días hábiles y por qué ese intervalo funciona bien.', 'sistema-4x4', 4, 3, '["Cada mensaje del 4x4 se envía, en promedio, cuatro días hábiles después del contacto anterior sin respuesta. Ese intervalo evita dos extremos: la presión de escribir todos los días y el olvido de dejar pasar semanas.","Cuatro días hábiles equivalen, en la mayoría de los casos, a poco menos de una semana calendario. Es tiempo suficiente para que la persona resuelva otras prioridades sin que la oportunidad se enfríe.","El intervalo es orientativo: si el cliente mencionó un calendario propio (por ejemplo, ''lo vemos en comité el día 20''), ese calendario tiene prioridad sobre la cadencia estándar."]'::jsonb, array['cadencia', 'cuatro días hábiles', 'frecuencia'], array['m4-l1'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m4-l5', 'mensaje-1-retomar-desde-lo-real', 'Mensaje 1: retomar desde lo real', 'Cómo iniciar el seguimiento retomando algo concreto de la conversación anterior.', 'sistema-4x4', 5, 3, '["El primer mensaje del ciclo se envía aproximadamente cuatro días hábiles después del último contacto útil. Su función es retomar algo real de la conversación anterior, no simplemente preguntar si vio el mensaje.","Debe proponer continuidad y buscar definir el próximo paso, con un llamado a la acción (CTA) concreto: una fecha, una pregunta puntual, una propuesta de reunión breve.","Evitar: ''Hola, ¿cómo estás? Cualquier cosa me avisás.'' Esa fórmula no retoma nada real ni propone nada concreto."]'::jsonb, array['mensaje 1', 'retomar', 'cta'], array['m1-l5', 'm4-l6'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m4-l6', 'mensaje-2-aportar-algo-tangible', 'Mensaje 2: aportar algo tangible', 'Cómo reducir la fricción incorporando un recurso concreto en el segundo contacto.', 'sistema-4x4', 6, 3, '["El segundo mensaje cambia el llamado a la acción respecto del primero: en lugar de simplemente preguntar, incorpora algo tangible que reduzca la fricción para decidir.","Puede tratarse de una web, un catálogo, un brochure, un ejemplo de trabajo anterior, una demo o cualquier recurso que aporte información nueva y útil.","El objetivo no es ''llenar'' el mensaje de enlaces, sino compartir un único recurso relevante que ayude a avanzar en la decisión concreta que la persona tiene pendiente."]'::jsonb, array['mensaje 2', 'recurso', 'tangible'], array['m4-l5', 'm4-l7'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m4-l7', 'mensaje-3-construir-validacion', 'Mensaje 3: construir validación', 'Cómo usar casos, testimonios o resultados para reducir la incertidumbre.', 'sistema-4x4', 7, 3, '["El tercer mensaje utiliza validación: un caso, un testimonio, un resultado concreto, una certificación o la trayectoria que respalde la propuesta.","La validación elegida debe relacionarse directamente con el problema o la necesidad del cliente. Un caso genérico, sin conexión con su situación, pierde efectividad.","Es importante no enviar un collage de enlaces ni varios casos a la vez. Un solo ejemplo bien elegido comunica más que una lista extensa."]'::jsonb, array['mensaje 3', 'validación', 'testimonio', 'caso'], array['m4-l6', 'm4-l8'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m4-l8', 'mensaje-4-cerrar-con-firmeza-amable', 'Mensaje 4: cerrar con firmeza amable', 'Cómo cerrar el ciclo sin insistir y sin cerrar la puerta definitivamente.', 'sistema-4x4', 8, 3, '["El cuarto mensaje cierra el hilo de seguimiento activo. Refuerza en una frase breve lo que está en juego para la persona, sin presionar ni sumar un quinto o sexto mensaje.","Este mensaje evita seguir insistiendo: no repite el pedido anterior, sino que ofrece una salida clara y respetuosa a la conversación.","Deja la puerta abierta explícitamente y puede derivar a una instancia de nurturing: dejar de escribir con frecuencia, pero mantener el vínculo con contenido de valor esporádico."]'::jsonb, array['mensaje 4', 'cierre', 'firmeza amable', 'nurturing'], array['m4-l7', 'm4-l9'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m4-l9', 'cuando-frenar-el-ciclo', 'Cuándo frenar el ciclo', 'Señales claras para detener el 4x4 antes de completar los cuatro mensajes.', 'sistema-4x4', 9, 2, '["El ciclo se detiene apenas el cliente responde, sin importar en qué mensaje del 4x4 estés. Responder con un nuevo seguimiento genérico después de que la persona ya contestó es un error frecuente.","También corresponde frenar el ciclo si la persona indicó explícitamente una fecha o un próximo paso concreto: en ese caso, se respeta esa fecha en lugar de continuar con la cadencia estándar.","Si la persona pide expresamente no recibir más mensajes, se detiene el seguimiento de inmediato."]'::jsonb, array['frenar', 'detener seguimiento', 'respuesta'], array['m4-l1', 'm1-l4'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m4-l10', 'que-es-nurturing', 'Qué es nurturing', 'Cómo mantener el vínculo con una oportunidad sin seguimiento activo.', 'sistema-4x4', 10, 3, '["Nurturing es la instancia posterior al cierre del ciclo 4x4: dejar de enviar mensajes de seguimiento frecuente, pero mantener el vínculo activo con contenido de valor esporádico.","Puede tratarse de compartir un artículo relevante, felicitar un logro público de la empresa o persona, o simplemente escribir cada varios meses para reabrir la conversación sin presión.","El nurturing reconoce que no todas las oportunidades están listas para decidir ahora, y que mantener una relación de largo plazo puede ser más valioso que forzar una respuesta inmediata."]'::jsonb, array['nurturing', 'vínculo', 'largo plazo'], array['m4-l8', 'm2-l4'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m4-l11', 'errores-frecuentes-del-seguimiento', 'Errores frecuentes del seguimiento', 'Los errores más comunes al aplicar seguimiento comercial, y cómo evitarlos.', 'sistema-4x4', 11, 4, '["Enviar siempre ''¿Pudiste verlo?'': no aporta información nueva ni facilita una respuesta. Es el ejemplo más común de seguimiento sin criterio.","Repetir el mismo mensaje con otras palabras: la persona percibe la falta de contenido nuevo, aunque el mensaje esté redactado distinto.","No aportar nada nuevo en cada contacto: cada mensaje del 4x4 debería sumar algo que el anterior no tenía.","Usar llamados a la acción abiertos, como ''cualquier cosa me escribís'': dificulta que la persona sepa qué se espera de ella.","Dejar conversaciones abiertas indefinidamente, sin proponer un cierre ni una fecha.","Seguir insistiendo después del cuarto contacto sin respuesta, en lugar de pasar a nurturing.","No respetar una fecha indicada por el cliente, escribiendo antes de lo acordado."]'::jsonb, array['errores', 'seguimiento', 'malas prácticas'], array['m1-l2', 'm4-l8'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m5-l1', 'que-es-una-objecion', 'Qué es una objeción', 'Una definición práctica para dejar de tratar las objeciones como un rechazo.', 'objeciones', 1, 3, '["Una objeción es una expresión de duda, resistencia o condición que la persona plantea antes de tomar una decisión. No es, en la mayoría de los casos, un rechazo definitivo.","Las objeciones suelen indicar que la persona todavía está evaluando, y que necesita más información, más confianza o más claridad para decidir.","Tratar una objeción como una pelea a ganar suele generar el efecto contrario al buscado. Tratarla como una oportunidad para entender mejor la situación del cliente, en cambio, facilita la decisión."]'::jsonb, array['objeción', 'definición'], array['m5-l2'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m5-l2', 'diferencia-objecion-duda-condicion', 'Diferencia entre objeción, duda y condición', 'Tres tipos de freno distintos que requieren respuestas distintas.', 'objeciones', 2, 3, '["Una duda es una falta de información: la persona no tiene claro algo puntual y, al aclararlo, puede avanzar sin problema.","Una objeción es una resistencia más profunda, relacionada con el precio, la prioridad, la confianza o la necesidad percibida.","Una condición es un requisito real que debe cumplirse antes de avanzar (por ejemplo, la aprobación de un tercero). Las condiciones no se argumentan: se gestionan.","Distinguir cuál de las tres situaciones enfrentás determina si conviene explicar, profundizar o simplemente acordar los próximos pasos."]'::jsonb, array['duda', 'condición', 'objeción'], array['m5-l1', 'm5-l6'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m5-l3', 'escuchar-antes-de-responder', 'Escuchar antes de responder', 'Por qué la primera reacción ante una objeción no debería ser argumentar.', 'objeciones', 3, 2, '["La reacción automática ante una objeción suele ser argumentar de inmediato. Sin embargo, responder antes de entender qué hay detrás de la objeción suele generar respuestas genéricas que no atienden la preocupación real.","Escuchar antes de responder significa darle espacio a la persona para explicar su freno, en lugar de interrumpir con una justificación preparada de antemano.","Esta pausa, además de generar mejor información, transmite que estás genuinamente interesado en resolver su situación y no solo en cerrar la venta."]'::jsonb, array['escuchar', 'objeción', 'reacción'], array['m5-l4'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m5-l4', 'preguntar-antes-de-argumentar', 'Preguntar antes de argumentar', 'El hábito que transforma una objeción en información útil para avanzar.', 'objeciones', 4, 3, '["Antes de responder una objeción, una buena pregunta ayuda a entender su origen real. Por ejemplo, ante ''es muy caro'', preguntar ''¿con qué lo estás comparando?'' aporta información valiosa antes de argumentar.","Preguntar no es ganar tiempo: es una forma legítima de entender si la objeción se relaciona con el precio, la prioridad, la confianza o la necesidad.","Una objeción bien explorada casi siempre revela un problema más específico y más fácil de resolver que la objeción original."]'::jsonb, array['preguntar', 'argumentar', 'objeción'], array['m5-l3', 'm5-l5'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m5-l5', 'evitar-justificar-de-mas', 'Cómo evitar justificar de más', 'Por qué dar demasiadas explicaciones puede debilitar tu posición.', 'objeciones', 5, 2, '["Cuando se recibe una objeción, es común encadenar varias justificaciones seguidas, casi a la defensiva. Esto puede transmitir inseguridad, aunque la intención sea generar confianza.","Una respuesta breve, clara y seguida de una pregunta suele ser más efectiva que una explicación extensa que intenta cubrir todos los ángulos posibles.","Justificar de más también puede introducir dudas que la persona ni siquiera tenía, al anticipar objeciones que no había planteado."]'::jsonb, array['justificar', 'explicaciones', 'seguridad'], array['m5-l4'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m5-l6', 'buscar-el-motivo-real', 'Cómo buscar el motivo real', 'Ir más allá de la objeción declarada para entender qué la origina.', 'objeciones', 6, 3, '["La objeción que se dice en voz alta no siempre es la razón real del freno. ''Necesito pensarlo'' puede esconder una duda sobre el precio, sobre la confianza en el resultado o sobre la prioridad actual.","Preguntas como ''¿qué es lo que más te gustaría pensar?'' o ''¿hay algo puntual que te genere dudas?'' ayudan a acercarse al motivo real sin sonar invasivo.","Encontrar el motivo real permite ofrecer una respuesta específica, en lugar de una respuesta genérica que no resuelve nada."]'::jsonb, array['motivo real', 'objeción', 'raíz'], array['m5-l2', 'm5-l7'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.lessons (id, slug, title, description, module_id, sort_order, estimated_minutes, content, keywords, related_lesson_ids, active)
values ('m5-l7', 'acordar-un-proximo-paso', 'Cómo acordar un próximo paso', 'El cierre correcto de cualquier conversación sobre una objeción.', 'objeciones', 7, 3, '["Responder una objeción sin proponer un próximo paso deja la conversación abierta otra vez. Toda respuesta a una objeción debería terminar con una propuesta concreta.","El próximo paso puede ser tan simple como acordar una fecha para retomar la conversación, o tan específico como ajustar la propuesta en un punto puntual.","Cerrar con un próximo paso claro transmite liderazgo del proceso, incluso cuando la respuesta de la persona todavía es una duda."]'::jsonb, array['próximo paso', 'objeción', 'cierre'], array['m5-l6', 'm2-l3'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, module_id = excluded.module_id, sort_order = excluded.sort_order, estimated_minutes = excluded.estimated_minutes, content = excluded.content, keywords = excluded.keywords, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('h-sin-conversacion', false, 'cualquiera', 'cualquiera', 'cualquiera', 'cualquiera', 'cualquiera', false, 'no_aplica_4x4', 'Todavía no corresponde aplicar el 4x4', 'El Sistema 4x4 se utiliza cuando ya existió una conversación, una respuesta o una manifestación de interés. Si la persona nunca respondió, estás frente a una instancia de contacto o reactivación, no de seguimiento.', 'Lograr una primera respuesta real, no insistir como si hubiera una oportunidad activa.', 'Revisá si el contacto es el adecuado, cambiá el ángulo del mensaje y aportá contexto o valor en lugar de repetir el pedido inicial.', 'Un contacto que nunca respondió necesita un mensaje distinto, no una repetición del primero.', 'Enviar cuatro mensajes de seguimiento como si ya existiera una oportunidad activa.', '{"requiredVariables":["nombre","contexto"],"template":"Hola {{nombre}}, te escribo porque {{contexto}}. Entiendo que puede no ser el mejor momento, así que quería simplemente dejarte esta puerta abierta por si te resulta de valor.","example":"Hola Lucas, te escribo porque vi que tu equipo está creciendo este semestre. Entiendo que puede no ser el mejor momento, así que quería simplemente dejarte esta puerta abierta por si te resulta de valor."}'::jsonb, '{"requiredVariables":["nombre","servicio"],"template":"Hola {{nombre}}, mi nombre es (tu nombre) y trabajo en {{servicio}}. Te escribo para presentarme brevemente, sin ningún compromiso. Si te interesa, con gusto te cuento más.","example":"Hola Lucas, mi nombre es (tu nombre) y trabajo en consultoría comercial. Te escribo para presentarme brevemente, sin ningún compromiso. Si te interesa, con gusto te cuento más."}'::jsonb, '{"requiredVariables":["nombre","necesidad"],"template":"Hola {{nombre}}, ¿tenés unos minutos esta semana para contarte cómo puedo ayudarte con {{necesidad}}?","example":"Hola Lucas, ¿tenés unos minutos esta semana para contarte cómo puedo ayudarte con la organización comercial de tu equipo?"}'::jsonb, array['m4-l2', 'm4-l3'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('i-fecha-evaluando', true, 'cualquiera', 'evaluando_propuesta', 'cualquiera', 'cualquiera', 'true', false, 'respetar_fecha', 'Respetar la fecha acordada', 'La persona ya te indicó una fecha o un próximo paso concreto. En este caso no corresponde aplicar el 4x4: corresponde respetar ese acuerdo y preparar la próxima intervención para ese momento.', 'Sostener el vínculo sin adelantarte a la fecha acordada, y llegar preparado a ella.', 'Marcá la fecha, preparate para esa instancia (revisar la propuesta, anticipar preguntas) y evitá escribir antes de tiempo.', 'Escribir antes de la fecha acordada puede transmitir apuro y erosionar la confianza generada.', 'No respetar una fecha indicada por el cliente y escribir de todos modos.', '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, como quedamos, te escribo el {{fecha}} para retomar. Mientras tanto, quedo disponible por cualquier duda que te surja.","example":"Hola Carolina, como quedamos, te escribo el jueves para retomar. Mientras tanto, quedo disponible por cualquier duda que te surja."}'::jsonb, '{"requiredVariables":["nombre","fecha","propuesta"],"template":"Hola {{nombre}}, tal como acordamos, retomamos el {{fecha}} la conversación sobre {{propuesta}}. Cualquier consulta antes de esa fecha, escribime.","example":"Hola Carolina, tal como acordamos, retomamos el jueves la conversación sobre la propuesta. Cualquier consulta antes de esa fecha, escribime."}'::jsonb, '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, confirmando que retomamos el {{fecha}} como quedamos.","example":"Hola Carolina, confirmando que retomamos el jueves como quedamos."}'::jsonb, array['m4-l9', 'm2-l3'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('i-fecha-tercero', true, 'cualquiera', 'hablarlo_con_tercero', 'cualquiera', 'cualquiera', 'true', false, 'respetar_fecha', 'Respetar la fecha acordada', 'La persona te indicó cuándo va a tener una respuesta después de hablarlo con un tercero. Corresponde esperar esa fecha en lugar de aplicar el 4x4.', 'Sostener el vínculo sin presionar antes de que se cumpla el plazo acordado.', 'Marcá la fecha y preparate para retomar con material breve para esa conversación, si todavía no lo enviaste.', 'Si podés, ofrecé un resumen breve para facilitar esa conversación con el tercero antes de la fecha acordada.', 'Escribir antes de la fecha para ''ver cómo va'', generando la sensación de presión.', '{"requiredVariables":["nombre","fecha","tercero"],"template":"Hola {{nombre}}, como hablamos, te escribo el {{fecha}} para conocer la respuesta luego de la charla con {{tercero}}. Si antes necesitás algo de mi parte, decime.","example":"Hola Bruno, como hablamos, te escribo el lunes para conocer la respuesta luego de la charla con tu equipo. Si antes necesitás algo de mi parte, decime."}'::jsonb, '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, retomamos el {{fecha}} como acordamos. Quedo atento.","example":"Hola Bruno, retomamos el lunes como acordamos. Quedo atento."}'::jsonb, '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, confirmo que te contacto el {{fecha}} como quedamos.","example":"Hola Bruno, confirmo que te contacto el lunes como quedamos."}'::jsonb, array['m4-l9'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('i-fecha-confirmo', true, 'cualquiera', 'confirmo_si_no_avanza', 'cualquiera', 'cualquiera', 'true', false, 'respetar_fecha', 'Respetar la fecha acordada', 'Ya confirmó que sí y además indicó una fecha concreta para destrabar el avance. Corresponde acompañar esa fecha, no reemplazarla por un seguimiento genérico.', 'Facilitar que el compromiso ya asumido se concrete en la fecha indicada.', 'Preparate para esa fecha con lo que la persona necesite de tu parte (firma, datos, coordinación) para no ser vos el cuello de botella.', 'Cuando alguien ya dijo que sí, tu tarea es quitar obstáculos, no agregar seguimiento adicional.', 'Enviar un mensaje de validación genérico cuando la persona ya confirmó y solo falta ejecutar.', '{"requiredVariables":["nombre","fecha","próximo_paso"],"template":"Hola {{nombre}}, genial que ya esté encaminado. Como quedamos para el {{fecha}}, te confirmo que estoy listo para {{próximo_paso}}.","example":"Hola Nadia, genial que ya esté encaminado. Como quedamos para el jueves, te confirmo que estoy listo para enviar el contrato."}'::jsonb, '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, confirmando que seguimos con lo acordado para el {{fecha}}.","example":"Hola Nadia, confirmando que seguimos con lo acordado para el jueves."}'::jsonb, '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, quedo atento para el {{fecha}} como quedamos.","example":"Hola Nadia, quedo atento para el jueves como quedamos."}'::jsonb, array['m4-l9'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('i-fecha-mas-adelante', true, 'cualquiera', 'conversemos_mas_adelante', 'cualquiera', 'cualquiera', 'true', false, 'respetar_fecha', 'Respetar la fecha acordada', 'La persona dio una fecha aproximada para retomar más adelante. Corresponde respetarla en lugar de iniciar un 4x4.', 'Mantener el vínculo sin generar la sensación de insistencia antes de tiempo.', 'Anotá la fecha aproximada y programá tu propio recordatorio para retomar en ese momento.', 'Un ''más adelante'' con fecha es un acuerdo, no una excusa: tratalo como tal.', 'Escribir antes del plazo mencionado por la persona.', '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, como hablamos, te escribo en {{fecha}}. Antes, cualquier cosa que necesites, quedo disponible.","example":"Hola Renata, como hablamos, te escribo en dos meses. Antes, cualquier cosa que necesites, quedo disponible."}'::jsonb, '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, retomamos en {{fecha}} tal como quedamos.","example":"Hola Renata, retomamos en dos meses tal como quedamos."}'::jsonb, '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, anotado. Te contacto en {{fecha}}.","example":"Hola Renata, anotado. Te contacto en dos meses."}'::jsonb, array['m4-l10'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('b-agendar-0', true, 'cualquiera', 'agendar_reunion', '0', 'cualquiera', 'cualquiera', true, 'preparar_contacto', 'Iniciar el contacto para coordinar', 'Buscás coordinar una llamada, turno o reunión y todavía no enviaste un mensaje sin respuesta desde el último intercambio.', 'Facilitar que la coordinación ocurra con el menor esfuerzo posible para la otra persona.', 'Proponé dos o tres opciones concretas de horario para reducir la fricción de coordinar.', 'Ofrecer opciones concretas de horario convierte una pregunta abierta en una decisión simple.', 'Preguntar ''¿cuándo te queda bien?'' sin proponer ninguna opción concreta.', '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, ¡qué bueno seguir avanzando! Para coordinar {{próximo_paso}}, ¿te vendría bien el martes o el jueves por la tarde?","example":"Hola Bianca, ¡qué bueno seguir avanzando! Para coordinar la llamada, ¿te vendría bien el martes o el jueves por la tarde?"}'::jsonb, '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, para coordinar {{próximo_paso}} te propongo martes o jueves. ¿Cuál te queda mejor?","example":"Hola Bianca, para coordinar la reunión te propongo martes o jueves. ¿Cuál te queda mejor?"}'::jsonb, '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, ¿coordinamos para el {{fecha}}?","example":"Hola Bianca, ¿coordinamos para el jueves a las 10?"}'::jsonb, array['m2-l3'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('b-agendar-1', true, 'cualquiera', 'agendar_reunion', '1', 'cualquiera', 'cualquiera', true, 'm1_retomar', 'Mensaje 1: retomar desde lo real', 'Enviaste una propuesta de horario y todavía no respondió. Es momento de retomar con un CTA concreto.', 'Definir el próximo paso: coordinar efectivamente la fecha de la reunión.', 'Retomá la propuesta de horario anterior y ofrecé una alternativa concreta para facilitar la respuesta.', 'Un mensaje corto con dos opciones de horario suele funcionar mejor que reiterar la pregunta abierta.', 'Repetir exactamente el mismo mensaje anterior.', '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, quería retomar lo de coordinar {{próximo_paso}}. Si el horario que propuse no te queda cómodo, decime qué día te viene mejor.","example":"Hola Bianca, quería retomar lo de coordinar la reunión. Si el horario que propuse no te queda cómodo, decime qué día te viene mejor."}'::jsonb, '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, siguiendo con lo de {{próximo_paso}}: ¿pudiste ver los horarios que te propuse?","example":"Hola Bianca, siguiendo con lo de coordinar la reunión: ¿pudiste ver los horarios que te propuse?"}'::jsonb, '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, ¿seguimos con el {{fecha}} o preferís otro día?","example":"Hola Bianca, ¿seguimos con el jueves o preferís otro día?"}'::jsonb, array['m4-l5'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('b-agendar-2', true, 'cualquiera', 'agendar_reunion', '2', 'cualquiera', 'cualquiera', true, 'm2_tangible', 'Mensaje 2: aportar algo tangible', 'Ya hiciste dos intentos de coordinar sin respuesta. Conviene reducir la fricción aportando algo tangible.', 'Reducir la fricción para que decidir un horario sea más simple.', 'Compartí un link de agenda o una agenda con disponibilidad concreta para que elija sin ida y vuelta.', 'Un link de agenda elimina por completo la fricción de coordinar por mensajes.', 'Volver a preguntar ''¿cuándo te queda bien?'' por tercera vez.', '{"requiredVariables":["nombre","recurso"],"template":"Hola {{nombre}}, para que sea más simple coordinar, te dejo {{recurso}} con mi disponibilidad. Elegí el horario que mejor te quede.","example":"Hola Bianca, para que sea más simple coordinar, te dejo mi calendario con mi disponibilidad. Elegí el horario que mejor te quede."}'::jsonb, '{"requiredVariables":["nombre","recurso"],"template":"Hola {{nombre}}, te comparto {{recurso}} para que elijas el horario que prefieras.","example":"Hola Bianca, te comparto el link de mi agenda para que elijas el horario que prefieras."}'::jsonb, '{"requiredVariables":["nombre","recurso"],"template":"Hola {{nombre}}, acá tenés {{recurso}}: elegí el horario y queda coordinado.","example":"Hola Bianca, acá tenés el link de mi agenda: elegí el horario y queda coordinado."}'::jsonb, array['m4-l6'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('b-agendar-3', true, 'cualquiera', 'agendar_reunion', '3', 'cualquiera', 'cualquiera', true, 'm4_cierre', 'Mensaje 4: cerrar con firmeza amable', 'Tres intentos sin respuesta para coordinar una simple reunión sugieren que no es el momento. Corresponde cerrar el hilo con amabilidad.', 'Cerrar el ciclo activo sin insistir, dejando la puerta abierta.', 'Enviá un mensaje breve que reconozca que quizás no es el momento y dejá la puerta abierta para que retome cuando quiera.', 'Cerrar el hilo con calidez suele generar más respuestas a largo plazo que seguir insistiendo.', 'Enviar un quinto mensaje pidiendo lo mismo.', '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, entiendo que quizás no sea el momento para coordinar esto. Quedo disponible cuando te venga bien retomarlo, sin ninguna urgencia.","example":"Hola Bianca, entiendo que quizás no sea el momento para coordinar esto. Quedo disponible cuando te venga bien retomarlo, sin ninguna urgencia."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, no quiero insistir de más. Quedo a disposición para coordinar cuando sea un buen momento para vos.","example":"Hola Bianca, no quiero insistir de más. Quedo a disposición para coordinar cuando sea un buen momento para vos."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, dejo esto abierto de mi lado. Escribime cuando quieras retomarlo.","example":"Hola Bianca, dejo esto abierto de mi lado. Escribime cuando quieras retomarlo."}'::jsonb, array['m4-l8'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('b-agendar-4', true, 'cualquiera', 'agendar_reunion', '4', 'cualquiera', 'cualquiera', false, 'nurturing', 'Nurturing', 'Cuatro o más intentos sin respuesta indican que corresponde detener el seguimiento activo y pasar a una relación de largo plazo.', 'Mantener el vínculo sin presión, con contactos esporádicos de valor.', 'Dejá de enviar mensajes de coordinación y retomá el contacto más adelante con contenido de valor, no con otro pedido de agenda.', 'El nurturing no es abandonar el vínculo: es cambiar la frecuencia y el tipo de contacto.', 'Seguir insistiendo después del cuarto contacto sin respuesta.', '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, no quiero saturarte. Voy a dejar de escribirte con esta frecuencia, pero quedo en contacto para más adelante.","example":"Hola Bianca, no quiero saturarte. Voy a dejar de escribirte con esta frecuencia, pero quedo en contacto para más adelante."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, dejo de insistir por ahora. Cuando sea un buen momento, quedo disponible.","example":"Hola Bianca, dejo de insistir por ahora. Cuando sea un buen momento, quedo disponible."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, lo dejamos acá por ahora. Cualquier novedad, contame.","example":"Hola Bianca, lo dejamos acá por ahora. Cualquier novedad, contame."}'::jsonb, array['m4-l10'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('c-proximo-paso-0', true, 'cualquiera', 'primera_conversacion_sin_proximo_paso', '0', 'cualquiera', 'cualquiera', true, 'preparar_contacto', 'Definir el próximo paso', 'Tuvieron una primera conversación, pero todavía no quedó definido qué sigue. Es el momento de proponerlo antes de que la conversación quede abierta.', 'Convertir una conversación exploratoria en un próximo paso concreto.', 'Proponé explícitamente cuál sería el siguiente paso: una propuesta, una segunda reunión o el envío de información.', 'Cuanto antes se defina un próximo paso, menor la probabilidad de que la conversación se enfríe.', 'Terminar la conversación con un genérico ''quedamos en contacto''.', '{"requiredVariables":["nombre","necesidad","próximo_paso"],"template":"Hola {{nombre}}, me quedé pensando en lo que hablamos sobre {{necesidad}}. Para seguir avanzando, ¿te parece que {{próximo_paso}}?","example":"Hola Federico, me quedé pensando en lo que hablamos sobre la necesidad de ordenar el proceso comercial. Para seguir avanzando, ¿te parece que coordinemos una segunda charla con más detalle?"}'::jsonb, '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, gracias por el tiempo de la charla. Como próximo paso, te propongo {{próximo_paso}}. ¿Te parece bien?","example":"Hola Federico, gracias por el tiempo de la charla. Como próximo paso, te propongo enviarte una propuesta esta semana. ¿Te parece bien?"}'::jsonb, '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, para seguir avanzando te propongo {{próximo_paso}}. ¿Vamos por ahí?","example":"Hola Federico, para seguir avanzando te propongo coordinar una reunión con tu equipo. ¿Vamos por ahí?"}'::jsonb, array['m2-l3', 'm2-l4'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('c-proximo-paso-1', true, 'cualquiera', 'primera_conversacion_sin_proximo_paso', '1', 'cualquiera', 'cualquiera', true, 'm1_retomar', 'Mensaje 1: retomar desde lo real', 'Ya propusiste un próximo paso y no obtuviste respuesta. Corresponde retomar con un CTA claro.', 'Obtener una definición sobre el próximo paso propuesto.', 'Retomá lo conversado y reforzá el próximo paso propuesto con una fecha concreta.', 'Agregar una fecha concreta a la propuesta anterior facilita la respuesta.', 'Enviar un ''¿pudiste ver mi mensaje?'' sin retomar contenido real.', '{"requiredVariables":["nombre","necesidad"],"template":"Hola {{nombre}}, quería retomar lo que hablamos sobre {{necesidad}}. ¿Te sirve si coordinamos para esta semana?","example":"Hola Federico, quería retomar lo que hablamos sobre ordenar el proceso comercial. ¿Te sirve si coordinamos para esta semana?"}'::jsonb, '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, siguiendo el hilo de nuestra charla: ¿avanzamos con {{próximo_paso}}?","example":"Hola Federico, siguiendo el hilo de nuestra charla: ¿avanzamos con la propuesta que te comenté?"}'::jsonb, '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, ¿coordinamos para el {{fecha}} como hablamos?","example":"Hola Federico, ¿coordinamos para el viernes como hablamos?"}'::jsonb, array['m4-l5'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('c-proximo-paso-2', true, 'cualquiera', 'primera_conversacion_sin_proximo_paso', '2', 'cualquiera', 'cualquiera', true, 'm2_tangible', 'Mensaje 2: aportar algo tangible', 'Dos contactos sin respuesta después de una primera conversación. Conviene aportar algo tangible que reduzca la fricción.', 'Aportar valor concreto que facilite decidir el próximo paso.', 'Compartí un recurso relacionado con lo conversado: un caso, una web o un material breve.', 'Un recurso concreto reactiva conversaciones que se enfriaron por falta de información.', 'Enviar el mismo mensaje de la primera vez con otras palabras.', '{"requiredVariables":["nombre","recurso","necesidad"],"template":"Hola {{nombre}}, pensando en lo que charlamos sobre {{necesidad}}, te comparto {{recurso}}. Puede darte más claridad para decidir cómo seguir.","example":"Hola Federico, pensando en lo que charlamos sobre ordenar el proceso comercial, te comparto un caso similar al tuyo. Puede darte más claridad para decidir cómo seguir."}'::jsonb, '{"requiredVariables":["nombre","recurso"],"template":"Hola {{nombre}}, te comparto {{recurso}} relacionado con lo que hablamos. Quedo atento a tus comentarios.","example":"Hola Federico, te comparto un material relacionado con lo que hablamos. Quedo atento a tus comentarios."}'::jsonb, '{"requiredVariables":["nombre","recurso"],"template":"Hola {{nombre}}, te dejo {{recurso}}. Decime si te sirve para definir el próximo paso.","example":"Hola Federico, te dejo el material. Decime si te sirve para definir el próximo paso."}'::jsonb, array['m4-l6'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('c-proximo-paso-3', true, 'cualquiera', 'primera_conversacion_sin_proximo_paso', '3', 'cualquiera', 'cualquiera', true, 'm3_validacion', 'Mensaje 3: construir validación', 'Tres contactos sin respuesta. Conviene construir confianza con una validación concreta antes de cerrar el ciclo.', 'Reducir la incertidumbre y construir confianza mediante una prueba concreta.', 'Elegí un caso, testimonio o resultado relacionado con la necesidad conversada.', 'La validación debe relacionarse directamente con el problema mencionado en la primera conversación.', 'Enviar varios casos o enlaces juntos en lugar de uno solo bien elegido.', '{"requiredVariables":["nombre","caso","resultado"],"template":"Hola {{nombre}}, quería compartirte {{caso}}, que partía de una situación parecida a la tuya. Lograron {{resultado}}, y creo que puede ayudarte a evaluar mejor cómo seguir.","example":"Hola Federico, quería compartirte el caso de una empresa de servicios similar a la tuya. Lograron ordenar su seguimiento comercial en dos meses, y creo que puede ayudarte a evaluar mejor cómo seguir."}'::jsonb, '{"requiredVariables":["nombre","caso"],"template":"Hola {{nombre}}, te comparto {{caso}} que puede ser relevante para tu situación. Quedo atento a tu opinión.","example":"Hola Federico, te comparto un caso reciente que puede ser relevante para tu situación. Quedo atento a tu opinión."}'::jsonb, '{"requiredVariables":["nombre","resultado"],"template":"Hola {{nombre}}, te dejo un ejemplo concreto de {{resultado}}. ¿Seguimos avanzando?","example":"Hola Federico, te dejo un ejemplo concreto de un proceso similar resuelto en pocas semanas. ¿Seguimos avanzando?"}'::jsonb, array['m4-l7'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('c-proximo-paso-4', true, 'cualquiera', 'primera_conversacion_sin_proximo_paso', '4', 'cualquiera', 'cualquiera', false, 'm4_cierre', 'Mensaje 4: cerrar con firmeza amable', 'Cuatro o más contactos sin respuesta luego de la primera conversación. Es momento de cerrar el hilo con amabilidad.', 'Cerrar el ciclo activo sin seguir insistiendo, dejando la puerta abierta.', 'Enviá un mensaje breve de cierre y pasá a nurturing.', 'Cerrar con criterio es más profesional que dejar la conversación en silencio indefinido.', 'Seguir enviando mensajes después del cuarto contacto sin respuesta.', '{"requiredVariables":["nombre","necesidad"],"template":"Hola {{nombre}}, entiendo que este no sea el momento para avanzar con {{necesidad}}. Quedo disponible para cuando lo sea, sin ningún apuro.","example":"Hola Federico, entiendo que este no sea el momento para avanzar con esto. Quedo disponible para cuando lo sea, sin ningún apuro."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, no quiero insistir de más. Quedo a disposición si más adelante querés retomarlo.","example":"Hola Federico, no quiero insistir de más. Quedo a disposición si más adelante querés retomarlo."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, lo dejo abierto de mi lado. Escribime cuando quieras retomar.","example":"Hola Federico, lo dejo abierto de mi lado. Escribime cuando quieras retomar."}'::jsonb, array['m4-l8', 'm4-l10'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('d-evaluando-generico', true, 'cualquiera', 'evaluando_propuesta', 'cualquiera', 'cualquiera', 'false', true, 'm3_validacion', 'Mensaje 3: construir validación', 'La persona está evaluando la propuesta, sin una fecha concreta de respuesta. Conviene aportar una validación que reduzca la incertidumbre de decidir.', 'Facilitar la evaluación con un elemento de confianza concreto.', 'Compartí un caso o resultado relacionado y proponé un próximo paso con fecha para resolver dudas.', 'Ofrecer ayuda concreta para evaluar (una llamada breve de dudas) suele acelerar la decisión más que esperar en silencio.', 'Preguntar ''¿alguna novedad?'' sin aportar nada que ayude a decidir.', '{"requiredVariables":["nombre","caso","próximo_paso"],"template":"Hola {{nombre}}, sé que estás evaluando la propuesta. Te comparto {{caso}} que puede darte más claridad. Si te sirve, coordinamos {{próximo_paso}} para resolver dudas.","example":"Hola Melina, sé que estás evaluando la propuesta. Te comparto un caso de una empresa que atravesó una decisión similar. Si te sirve, coordinamos una llamada breve para resolver dudas."}'::jsonb, '{"requiredVariables":["nombre","caso"],"template":"Hola {{nombre}}, mientras evaluás la propuesta, te dejo {{caso}} que puede ser útil. Cualquier duda, quedo disponible.","example":"Hola Melina, mientras evaluás la propuesta, te dejo un caso reciente que puede ser útil. Cualquier duda, quedo disponible."}'::jsonb, '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, ¿te sirve que coordinemos {{próximo_paso}} para resolver dudas y avanzar?","example":"Hola Melina, ¿te sirve que coordinemos una llamada de 15 minutos para resolver dudas y avanzar?"}'::jsonb, array['m4-l7', 'm5-l6'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('e-confirmo-sin-avance', true, 'cualquiera', 'confirmo_si_no_avanza', 'cualquiera', 'cualquiera', 'false', true, 'facilitar_compromiso', 'Facilitar el compromiso ya asumido', 'La persona ya confirmó que avanza, pero el avance concreto no se concreta. Esto no requiere una validación genérica: requiere facilitar la acción comprometida.', 'Quitar obstáculos para que el compromiso ya asumido se concrete.', 'Identificá qué está faltando (firma, datos, un pago, una coordinación) y ofrecé resolverlo vos, si es posible.', 'Cuando alguien ya dijo que sí, la tarea es facilitar la ejecución, no convencer de nuevo.', 'Enviar un mensaje de validación o casos de éxito, como si todavía estuviera decidiendo.', '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, sé que ya está encaminado. Para que podamos concretar {{próximo_paso}}, ¿hay algo de mi parte que te esté faltando?","example":"Hola Ariel, sé que ya está encaminado. Para que podamos concretar el inicio del proyecto, ¿hay algo de mi parte que te esté faltando?"}'::jsonb, '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, para avanzar con {{próximo_paso}}, contame si necesitás algo puntual de mi lado.","example":"Hola Ariel, para avanzar con la firma del contrato, contame si necesitás algo puntual de mi lado."}'::jsonb, '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, ¿qué falta para cerrar {{próximo_paso}}? Lo resolvemos.","example":"Hola Ariel, ¿qué falta para cerrar la firma del contrato? Lo resolvemos."}'::jsonb, array['m2-l3'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('f-tercero-sin-fecha', true, 'cualquiera', 'hablarlo_con_tercero', 'cualquiera', 'cualquiera', 'false', true, 'facilitar_tercero', 'Facilitar la conversación con el tercero', 'La decisión depende de otra persona y todavía no hay una fecha. La ayuda más útil es facilitar esa conversación, no seguir esperando en silencio.', 'Facilitar que la conversación con el tercero ocurra con la información necesaria.', 'Ofrecé un resumen breve para compartir y preguntá si sería útil coordinar una charla entre todos.', 'Un resumen de una página suele ser más efectivo que dejar que la persona explique la propuesta de memoria.', 'Preguntar simplemente ''¿alguna novedad?'' sin ofrecer ayuda concreta.', '{"requiredVariables":["nombre","tercero"],"template":"Hola {{nombre}}, para que sea más fácil conversarlo con {{tercero}}, te armo un resumen breve. ¿Te sirve?","example":"Hola Paula, para que sea más fácil conversarlo con tu socio, te armo un resumen breve. ¿Te sirve?"}'::jsonb, '{"requiredVariables":["nombre","tercero"],"template":"Hola {{nombre}}, ¿te ayudaría un resumen de los puntos clave para compartir con {{tercero}}?","example":"Hola Paula, ¿te ayudaría un resumen de los puntos clave para compartir con tu socio?"}'::jsonb, '{"requiredVariables":["nombre","tercero","fecha"],"template":"Hola {{nombre}}, te paso un resumen para {{tercero}}. ¿Coordinamos una charla los tres el {{fecha}}?","example":"Hola Paula, te paso un resumen para tu socio. ¿Coordinamos una charla los tres el viernes?"}'::jsonb, array['m5-l2'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('g-mas-adelante-sin-fecha', true, 'cualquiera', 'conversemos_mas_adelante', 'cualquiera', 'cualquiera', 'false', false, 'preparar_contacto', 'Acordar una fecha aproximada', 'La persona pidió retomarlo más adelante, pero no dio una fecha concreta. Antes de aplicar cualquier cadencia, conviene acordar un horizonte de tiempo.', 'Obtener una fecha aproximada de recontacto para no quedar en una espera indefinida.', 'Preguntá por un plazo aproximado y proponé quedar en contacto para ese momento.', 'Un ''más adelante'' sin fecha se convierte fácilmente en una conversación olvidada. Acordar un plazo, aunque sea aproximado, evita eso.', 'Aceptar el ''más adelante'' sin preguntar cuándo sería un buen momento.', '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, por supuesto, entiendo que no sea el momento. Para no perderlo de vista, ¿tenés una idea aproximada de cuándo te gustaría retomarlo?","example":"Hola Ignacio, por supuesto, entiendo que no sea el momento. Para no perderlo de vista, ¿tenés una idea aproximada de cuándo te gustaría retomarlo?"}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, entendido. ¿Te parece si acordamos un plazo aproximado para retomar la conversación?","example":"Hola Ignacio, entendido. ¿Te parece si acordamos un plazo aproximado para retomar la conversación?"}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, ¿en cuánto tiempo te parece bien que retome el contacto?","example":"Hola Ignacio, ¿en cuánto tiempo te parece bien que retome el contacto?"}'::jsonb, array['m4-l10'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('reuniones-falta-avanzar', true, 'cualquiera', 'reuniones_falta_avanzar', 'cualquiera', 'cualquiera', 'cualquiera', true, 'm2_tangible', 'Aportar algo tangible para destrabar', 'Ya hubo una o más reuniones, pero falta avanzar. Aportar un recurso concreto ayuda a que el siguiente paso sea más fácil de tomar.', 'Reducir la fricción para pasar de las reuniones a una definición concreta.', 'Compartí un resumen de lo conversado en las reuniones junto con un próximo paso claro y una fecha.', 'Después de varias reuniones sin avance, un resumen escrito ayuda a poner en común lo hablado y evita reprocesar todo de nuevo.', 'Proponer otra reunión más sin ofrecer nada nuevo respecto a las anteriores.', '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, después de todo lo conversado, te armé un resumen con lo hablado. Como próximo paso, te propongo {{próximo_paso}}. ¿Vamos por ahí?","example":"Hola Wanda, después de todo lo conversado, te armé un resumen con lo hablado. Como próximo paso, te propongo enviarte la propuesta formal esta semana. ¿Vamos por ahí?"}'::jsonb, '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, retomando las reuniones anteriores, te propongo como próximo paso {{próximo_paso}}.","example":"Hola Wanda, retomando las reuniones anteriores, te propongo como próximo paso definir el alcance final esta semana."}'::jsonb, '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, para no dar más vueltas: propongo {{próximo_paso}}. ¿Te sirve?","example":"Hola Wanda, para no dar más vueltas: propongo enviar la propuesta esta semana. ¿Te sirve?"}'::jsonb, array['m2-l3', 'm4-l6'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('pendiente-coordinar-reunion', true, 'cualquiera', 'pendiente_coordinar_reunion', 'cualquiera', 'cualquiera', 'cualquiera', false, 'preparar_reunion', 'Preparar la coordinación de la reunión', 'Ya existe una reunión pendiente de coordinar. No corresponde iniciar un 4x4: corresponde una rutina simple para cerrar la coordinación.', 'Concretar la fecha y hora de la reunión pendiente.', 'Proponé opciones concretas de horario y confirmá por escrito una vez acordado.', 'Cuanto más concretas las opciones que ofrezcas, más rápido se cierra la coordinación.', 'Dejar la coordinación abierta sin proponer horarios específicos.', '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, para coordinar nuestra reunión pendiente, ¿te vendría bien esta semana? Decime qué día y horario te queda mejor.","example":"Hola Emiliano, para coordinar nuestra reunión pendiente, ¿te vendría bien esta semana? Decime qué día y horario te queda mejor."}'::jsonb, '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, quedó pendiente coordinar la reunión. Te propongo el {{fecha}}. ¿Te queda bien?","example":"Hola Emiliano, quedó pendiente coordinar la reunión. Te propongo el miércoles a las 11. ¿Te queda bien?"}'::jsonb, '{"requiredVariables":["nombre","fecha"],"template":"Hola {{nombre}}, ¿coordinamos la reunión para el {{fecha}}?","example":"Hola Emiliano, ¿coordinamos la reunión para el miércoles a las 11?"}'::jsonb, array['m2-l3'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('enviar-propuesta', true, 'cualquiera', 'enviar_propuesta', 'cualquiera', 'cualquiera', 'cualquiera', false, 'preparar_propuesta', 'Preparar y acordar cómo presentar la propuesta', 'Tenés que enviar o presentar una propuesta. La acción no es de seguimiento todavía, sino de preparación: definir el contenido y cómo se va a presentar.', 'Enviar una propuesta clara y acordar cómo se va a presentar o revisar.', 'Preparála con base en lo conversado y proponé si conviene enviarla por escrito o presentarla en una breve llamada.', 'Ofrecer presentar la propuesta en una llamada breve suele generar mejores conversaciones que enviarla y esperar en silencio.', 'Enviar la propuesta sin proponer ningún próximo paso para conversarla después.', '{"requiredVariables":["nombre","propuesta"],"template":"Hola {{nombre}}, ya tengo lista {{propuesta}}. ¿Preferís que te la envíe para revisar con calma, o coordinamos una llamada breve para presentártela?","example":"Hola Camilo, ya tengo lista la propuesta. ¿Preferís que te la envíe para revisar con calma, o coordinamos una llamada breve para presentártela?"}'::jsonb, '{"requiredVariables":["nombre","propuesta"],"template":"Hola {{nombre}}, te comparto {{propuesta}}. Quedo disponible para resolver dudas cuando la revises.","example":"Hola Camilo, te comparto la propuesta. Quedo disponible para resolver dudas cuando la revises."}'::jsonb, '{"requiredVariables":["nombre","propuesta","fecha"],"template":"Hola {{nombre}}, te envío {{propuesta}}. ¿Coordinamos el {{fecha}} para repasarla juntos?","example":"Hola Camilo, te envío la propuesta. ¿Coordinamos el jueves para repasarla juntos?"}'::jsonb, array['m2-l3'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('otra-situacion', true, 'cualquiera', 'otra_situacion', 'cualquiera', 'cualquiera', 'cualquiera', true, 'sin_coincidencia', 'Situación particular', 'Tu situación no encaja exactamente con las rutas predefinidas de Potentia. Esto no significa que no puedas accionar: significa que conviene aplicar los criterios generales del Sistema 4x4 con tu propio criterio.', 'Aplicar los principios generales del seguimiento (retomar, aportar, validar, cerrar) adaptados a tu caso particular.', 'Revisá los contenidos relacionados sobre el Sistema 4x4 y elegí manualmente qué función necesita tu próximo mensaje: retomar, aportar algo tangible, validar o cerrar.', 'Ninguna matriz puede prever todas las situaciones reales. Usá el criterio de las cuatro funciones del 4x4 como guía.', 'Forzar tu situación dentro de una recomendación que no encaja realmente.', '{"requiredVariables":["nombre","contexto"],"template":"Hola {{nombre}}, quería retomar contacto respecto a {{contexto}}. Contame cómo seguís pensándolo, así te ayudo con lo que necesites.","example":"Hola, quería retomar contacto respecto a lo que veníamos conversando. Contame cómo seguís pensándolo, así te ayudo con lo que necesites."}'::jsonb, '{"requiredVariables":["nombre","contexto"],"template":"Hola {{nombre}}, escribo para retomar {{contexto}}. Quedo atento a tus novedades.","example":"Hola, escribo para retomar el tema que veníamos conversando. Quedo atento a tus novedades."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, ¿cómo seguimos con esto?","example":"Hola, ¿cómo seguimos con esto?"}'::jsonb, array['m4-l1', 'm4-l11'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('a-propuesta-0', true, 'cualquiera', 'propuesta_sin_respuesta', '0', 'cualquiera', 'false', true, 'preparar_contacto', 'Preparar el primer contacto de seguimiento', 'Enviaste la propuesta y todavía no pasó tiempo suficiente como para considerar que no hay respuesta. Es el momento de preparar, no de escribir todavía.', 'Tener listo el primer mensaje de seguimiento para cuando corresponda enviarlo.', 'Definí una fecha (aproximadamente cuatro días hábiles desde el envío) para el primer contacto de seguimiento si no hay novedades antes.', 'Escribir demasiado pronto después de enviar una propuesta puede transmitir ansiedad. Cuatro días hábiles es un buen punto de partida.', 'Escribir al día siguiente de enviar la propuesta.', '{"requiredVariables":["nombre","propuesta"],"template":"Hola {{nombre}}, te dejo por acá {{propuesta}}. Cualquier duda que te surja mientras la revisás, quedo disponible.","example":"Hola Delfina, te dejo por acá la propuesta. Cualquier duda que te surja mientras la revisás, quedo disponible."}'::jsonb, '{"requiredVariables":["nombre","propuesta"],"template":"Hola {{nombre}}, adjunto {{propuesta}} para tu revisión. Quedo atento a tus comentarios.","example":"Hola Delfina, adjunto la propuesta para tu revisión. Quedo atento a tus comentarios."}'::jsonb, '{"requiredVariables":["nombre","propuesta"],"template":"Hola {{nombre}}, te comparto {{propuesta}}. Avisame cualquier cosa.","example":"Hola Delfina, te comparto la propuesta. Avisame cualquier cosa."}'::jsonb, array['m4-l4'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('a-propuesta-1', true, 'cualquiera', 'propuesta_sin_respuesta', '1', 'cualquiera', 'false', true, 'm2_tangible', 'Mensaje 2: aportar algo tangible', 'Ya hiciste un primer contacto de seguimiento sin respuesta. El mensaje 2 cambia el llamado a la acción e incorpora algo tangible.', 'Reducir la fricción para decidir aportando un recurso concreto.', 'Compartí un recurso relacionado con la propuesta: un ejemplo, una demo o material de referencia.', 'Aportar un recurso nuevo demuestra que el mensaje no es una repetición del anterior.', 'Repetir ''¿pudiste ver la propuesta?'' por segunda vez.', '{"requiredVariables":["nombre","recurso","necesidad"],"template":"Hola {{nombre}}, pensando en {{necesidad}}, te comparto {{recurso}} que puede darte más contexto sobre la propuesta.","example":"Hola Delfina, pensando en la necesidad de mejorar el seguimiento comercial, te comparto un ejemplo de cómo trabajamos con otro cliente similar."}'::jsonb, '{"requiredVariables":["nombre","recurso"],"template":"Hola {{nombre}}, te comparto {{recurso}} como complemento a la propuesta enviada.","example":"Hola Delfina, te comparto un caso de referencia como complemento a la propuesta enviada."}'::jsonb, '{"requiredVariables":["nombre","recurso"],"template":"Hola {{nombre}}, te dejo {{recurso}} para que tengas más elementos.","example":"Hola Delfina, te dejo un ejemplo concreto para que tengas más elementos."}'::jsonb, array['m4-l6'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('a-propuesta-2', true, 'empresa', 'propuesta_sin_respuesta', '2', 'email', 'false', true, 'm3_validacion', 'Mensaje 3: validación', 'Ya compartiste la propuesta y realizaste dos contactos sin respuesta, vendiéndole a una empresa por correo electrónico. Corresponde construir confianza con una validación concreta.', 'Reducir la incertidumbre y construir confianza mediante una prueba concreta relacionada con la necesidad del cliente.', 'Elegí un caso, testimonio, resultado o respaldo que ayude a la persona a evaluar mejor la propuesta. Evitá enviar muchos casos o enlaces juntos: uno solo, bien elegido.', 'En correo electrónico, un mensaje algo más estructurado (con un asunto claro) suele funcionar mejor que uno muy breve.', 'Enviar un collage de enlaces o varios casos a la vez en lugar de un ejemplo bien elegido.', '{"requiredVariables":["nombre","necesidad","caso","resultado","próximo_paso"],"template":"Hola {{nombre}}. Pensando en lo que conversamos sobre {{necesidad}}, quería compartirte {{caso}}, porque partían de una situación similar. En ese proceso lograron {{resultado}}. Creo que puede darte más claridad para evaluar la propuesta. ¿Te parece que coordinemos {{próximo_paso}}?","example":"Hola Marina. Pensando en lo que conversamos sobre ordenar el seguimiento comercial del equipo, quería compartirte el caso de una empresa de servicios profesionales con un equipo de tamaño similar al tuyo. En ese proceso lograron reducir a la mitad el tiempo que tardaban en responder propuestas pendientes. Creo que puede darte más claridad para evaluar la propuesta. ¿Te parece que coordinemos una llamada breve esta semana?"}'::jsonb, '{"requiredVariables":["nombre","propuesta","caso","próximo_paso"],"template":"Hola {{nombre}}, retomo el envío de {{propuesta}}. Te comparto {{caso}}, que puede ser un buen punto de referencia para tu evaluación. Quedo disponible para coordinar {{próximo_paso}} cuando te resulte oportuno.","example":"Hola Marina, retomo el envío de la propuesta comercial. Te comparto el caso de una empresa similar que atravesó un proceso de decisión parecido, que puede ser un buen punto de referencia para tu evaluación. Quedo disponible para coordinar una breve llamada cuando te resulte oportuno."}'::jsonb, '{"requiredVariables":["nombre","resultado","próximo_paso"],"template":"Hola {{nombre}}, te comparto un resultado concreto de un proceso similar: {{resultado}}. ¿Coordinamos {{próximo_paso}} esta semana para resolver dudas sobre la propuesta?","example":"Hola Marina, te comparto un resultado concreto de un proceso similar: ordenaron su seguimiento comercial y redujeron a la mitad el tiempo de respuesta a propuestas. ¿Coordinamos una llamada de 15 minutos esta semana para resolver dudas sobre la propuesta?"}'::jsonb, array['m4-l7', 'm2-l4'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('a-propuesta-2-persona-whatsapp', true, 'persona', 'propuesta_sin_respuesta', '2', 'whatsapp', 'false', true, 'm3_validacion', 'Mensaje 3: validación', 'Le vendés a una persona, por WhatsApp, y ya van dos contactos sin respuesta después de enviar la propuesta. Corresponde una validación breve y conversacional, acorde al canal.', 'Reducir la incertidumbre con un ejemplo breve, en un formato natural para WhatsApp.', 'Compartí en pocas líneas un resultado o testimonio concreto, sin extenderte demasiado.', 'En WhatsApp, los mensajes largos suelen leerse peor. Priorizá la brevedad, incluso al compartir una validación.', 'Escribir un mensaje muy largo, poco natural para el formato de WhatsApp.', '{"requiredVariables":["nombre","resultado"],"template":"Hola {{nombre}} 🙂 te cuento rápido: hace poco ayudé a alguien en una situación parecida y logró {{resultado}}. Capaz te sirve para decidir con más tranquilidad. ¿Cómo venís pensándolo?","example":"Hola Yamila 🙂 te cuento rápido: hace poco ayudé a alguien en una situación parecida y logró ordenar su seguimiento en pocas semanas. Capaz te sirve para decidir con más tranquilidad. ¿Cómo venís pensándolo?"}'::jsonb, '{"requiredVariables":["nombre","resultado"],"template":"Hola {{nombre}}, te comparto un ejemplo breve: {{resultado}}. Quedo atento si tenés dudas sobre la propuesta.","example":"Hola Yamila, te comparto un ejemplo breve: una persona en tu misma situación logró resolverlo en pocas semanas. Quedo atento si tenés dudas sobre la propuesta."}'::jsonb, '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, ¿charlamos 10 minutos por {{próximo_paso}} para resolver dudas de la propuesta?","example":"Hola Yamila, ¿charlamos 10 minutos por videollamada para resolver dudas de la propuesta?"}'::jsonb, array['m4-l7'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('a-propuesta-2-linkedin', true, 'empresa', 'propuesta_sin_respuesta', '2', 'linkedin', 'false', true, 'm3_validacion', 'Mensaje 3: validación', 'Dos contactos sin respuesta por LinkedIn después de compartir la propuesta. Conviene un mensaje breve y profesional, con una validación puntual.', 'Reforzar la credibilidad con un dato concreto, en un formato breve y profesional.', 'Mencioná brevemente un resultado o caso relevante, sin extenderte demasiado en el mensaje.', 'En LinkedIn, los mensajes muy extensos reducen la tasa de respuesta. Priorizá un mensaje corto y concreto.', 'Escribir un mensaje largo, poco habitual para el formato de la plataforma.', '{"requiredVariables":["nombre","resultado"],"template":"Hola {{nombre}}, espero que estés bien. Quería compartirte brevemente que un cliente en una situación similar logró {{resultado}}. Quedo atento si te sirve conversarlo.","example":"Hola Rodrigo, espero que estés bien. Quería compartirte brevemente que un cliente en una situación similar logró mejorar sus tiempos de respuesta comercial. Quedo atento si te sirve conversarlo."}'::jsonb, '{"requiredVariables":["nombre","caso"],"template":"Hola {{nombre}}, te comparto {{caso}} como referencia adicional a la propuesta enviada. Saludos.","example":"Hola Rodrigo, te comparto un caso reciente como referencia adicional a la propuesta enviada. Saludos."}'::jsonb, '{"requiredVariables":["nombre","próximo_paso"],"template":"Hola {{nombre}}, ¿te sirve coordinar {{próximo_paso}} para resolver dudas sobre la propuesta?","example":"Hola Rodrigo, ¿te sirve coordinar una llamada breve para resolver dudas sobre la propuesta?"}'::jsonb, array['m4-l7'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('a-propuesta-2-instagram', true, 'persona', 'propuesta_sin_respuesta', '2', 'instagram', 'false', true, 'm3_validacion', 'Mensaje 3: validación', 'Dos contactos sin respuesta por Instagram luego de compartir la propuesta. Conviene un mensaje corto, natural y cercano al tono del canal.', 'Aportar un ejemplo cercano que genere confianza, en un tono natural.', 'Compartí un resultado breve en tono conversacional, coherente con el canal.', 'En Instagram, los mensajes muy formales desentonan. Mantené un tono natural y cercano, sin perder claridad.', 'Usar un tono demasiado formal, poco natural para la plataforma.', '{"requiredVariables":["nombre","resultado"],"template":"Holaa {{nombre}}, te cuento que a alguien en una situación parecida le fue muy bien: logró {{resultado}}. Si querés te cuento más 🙂","example":"Holaa Cande, te cuento que a alguien en una situación parecida le fue muy bien: logró ordenar sus seguimientos y cerrar más rápido. Si querés te cuento más 🙂"}'::jsonb, '{"requiredVariables":["nombre","resultado"],"template":"Hola {{nombre}}, te comparto un ejemplo breve: {{resultado}}. Cualquier duda, avisame.","example":"Hola Cande, te comparto un ejemplo breve: alguien en tu misma situación lo resolvió en pocas semanas. Cualquier duda, avisame."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, ¿cómo la venís pensando? Te cuento un caso si te sirve.","example":"Hola Cande, ¿cómo la venís pensando? Te cuento un caso si te sirve."}'::jsonb, array['m4-l7'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('a-propuesta-2-verbal', true, 'cualquiera', 'propuesta_sin_respuesta', '2', 'verbal', 'false', true, 'm3_validacion', 'Mensaje 3: validación (guion para llamada)', 'Estás en una conversación verbal o telefónica y ya hiciste dos intentos sin respuesta. Acá no corresponde un mensaje escrito, sino un guion breve para la llamada.', 'Tener preparado qué decir para construir confianza apenas se logre el contacto verbal.', 'Preparate un guion breve con un ejemplo concreto para mencionar apenas la persona atienda o devuelva la llamada.', 'Un guion no debe sonar leído: usalo como guía de los puntos clave, no como texto para recitar.', 'Improvisar sin ningún ejemplo concreto preparado de antemano.', '{"requiredVariables":["nombre","resultado"],"template":"Guion sugerido: ''Hola {{nombre}}, quería contarte sobre un caso reciente en el que logramos {{resultado}}, pensando en tu situación. ¿Tenés unos minutos para que te cuente cómo se aplicaría a tu caso?''","example":"Guion sugerido: ''Hola Esteban, quería contarte sobre un caso reciente en el que logramos ordenar el seguimiento comercial de un equipo similar al tuyo. ¿Tenés unos minutos para que te cuente cómo se aplicaría a tu caso?''"}'::jsonb, '{"requiredVariables":["nombre","caso"],"template":"Guion sugerido: ''Hola {{nombre}}, te llamo para comentarte {{caso}}, que puede ser un buen punto de referencia para la propuesta que te envié.''","example":"Guion sugerido: ''Hola Esteban, te llamo para comentarte un caso reciente, que puede ser un buen punto de referencia para la propuesta que te envié.''"}'::jsonb, '{"requiredVariables":["nombre"],"template":"Guion sugerido: ''Hola {{nombre}}, quería saber cómo seguís pensando la propuesta y contarte un ejemplo concreto que puede ayudarte a decidir.''","example":"Guion sugerido: ''Hola Esteban, quería saber cómo seguís pensando la propuesta y contarte un ejemplo concreto que puede ayudarte a decidir.''"}'::jsonb, array['m4-l7'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('a-propuesta-3', true, 'cualquiera', 'propuesta_sin_respuesta', '3', 'cualquiera', 'false', true, 'm4_cierre', 'Mensaje 4: cerrar con firmeza amable', 'Tres contactos sin respuesta después de la propuesta. Corresponde cerrar el hilo con firmeza amable, sin sumar un quinto mensaje.', 'Cerrar el ciclo activo, reforzando en una frase lo que está en juego, y dejar la puerta abierta.', 'Enviá un mensaje breve de cierre que reconozca la falta de respuesta sin reprochar, y proponé una salida clara.', 'Un buen cierre puede reactivar una respuesta que la insistencia no logró.', 'Enviar un quinto mensaje repitiendo el pedido de siempre.', '{"requiredVariables":["nombre","necesidad"],"template":"Hola {{nombre}}, entiendo que puede no ser el momento para avanzar con {{necesidad}}. No quiero insistir de más: quedo disponible para cuando te resulte oportuno retomarlo.","example":"Hola Delfina, entiendo que puede no ser el momento para avanzar con esto. No quiero insistir de más: quedo disponible para cuando te resulte oportuno retomarlo."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, no he tenido novedades tuyas sobre la propuesta. Voy a dejar de escribir por ahora, pero quedo a disposición si más adelante querés retomarlo.","example":"Hola Delfina, no he tenido novedades tuyas sobre la propuesta. Voy a dejar de escribir por ahora, pero quedo a disposición si más adelante querés retomarlo."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, lo dejo abierto de mi lado. Escribime cuando quieras retomar la propuesta.","example":"Hola Delfina, lo dejo abierto de mi lado. Escribime cuando quieras retomar la propuesta."}'::jsonb, array['m4-l8'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('a-propuesta-4', true, 'cualquiera', 'propuesta_sin_respuesta', '4', 'cualquiera', 'false', false, 'nurturing', 'Nurturing', 'Cuatro o más contactos sin respuesta luego de la propuesta. El ciclo activo terminó: corresponde pasar a nurturing.', 'Mantener el vínculo sin presión, a través de contactos esporádicos de valor.', 'Dejá de enviar seguimiento frecuente. Retomá el contacto en unas semanas o meses con contenido de valor, no con un nuevo pedido de respuesta.', 'El nurturing bien aplicado mantiene abiertas oportunidades que, de otro modo, se perderían por completo.', 'Seguir insistiendo con la propuesta después del cuarto contacto sin respuesta.', '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, no quiero saturarte con mensajes. Voy a dejar de escribir con esta frecuencia, pero quedo en contacto para más adelante, cuando te resulte oportuno.","example":"Hola Delfina, no quiero saturarte con mensajes. Voy a dejar de escribir con esta frecuencia, pero quedo en contacto para más adelante, cuando te resulte oportuno."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, dejo de insistir con la propuesta por ahora. Quedo disponible para retomar cuando sea un buen momento.","example":"Hola Delfina, dejo de insistir con la propuesta por ahora. Quedo disponible para retomar cuando sea un buen momento."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, lo dejamos acá por ahora. Cualquier novedad de tu lado, contame.","example":"Hola Delfina, lo dejamos acá por ahora. Cualquier novedad de tu lado, contame."}'::jsonb, array['m4-l10'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.action_matrix_entries (id, has_previous_conversation, sale_type, opportunity_stage, unanswered_messages, channel, has_agreed_date, applies_4x4, recommended_stage, stage_name, interpretation, objective, suggested_action, advice, mistake_to_avoid, empathetic_message, neutral_message, direct_message, related_lesson_ids, active)
values ('comparti-precio-generico', true, 'cualquiera', 'comparti_precio', 'cualquiera', 'cualquiera', 'false', true, 'm2_tangible', 'Mensaje 2: aportar algo tangible', 'Ya compartiste el precio o la cotización. Antes de la validación, suele ayudar aportar algo tangible que reduzca dudas sobre lo que incluye.', 'Reducir dudas sobre el alcance y facilitar la comparación de valor.', 'Compartí un detalle de lo que incluye el precio o un ejemplo de resultado esperado, para facilitar la evaluación.', 'Cuando el freno puede ser el precio, aportar claridad sobre el alcance suele ser más efectivo que insistir en el monto.', 'Bajar el precio de forma automática sin entender antes qué genera la duda.', '{"requiredVariables":["nombre","propuesta","recurso"],"template":"Hola {{nombre}}, quería compartirte {{recurso}} para que tengas más claridad sobre lo que incluye {{propuesta}}. Cualquier duda, con gusto la conversamos.","example":"Hola Santino, quería compartirte un detalle de lo que incluye la cotización para que tengas más claridad. Cualquier duda, con gusto la conversamos."}'::jsonb, '{"requiredVariables":["nombre","propuesta"],"template":"Hola {{nombre}}, retomo el envío de {{propuesta}}. Si te sirve, puedo detallar mejor el alcance para facilitar tu evaluación.","example":"Hola Santino, retomo el envío de la cotización. Si te sirve, puedo detallar mejor el alcance para facilitar tu evaluación."}'::jsonb, '{"requiredVariables":["nombre"],"template":"Hola {{nombre}}, ¿tenés dudas puntuales sobre el precio o el alcance que te haya compartido? Te las resuelvo.","example":"Hola Santino, ¿tenés dudas puntuales sobre el precio o el alcance que te haya compartido? Te las resuelvo."}'::jsonb, array['m5-l1', 'm4-l6'], true)
on conflict (id) do update set has_previous_conversation = excluded.has_previous_conversation, sale_type = excluded.sale_type, opportunity_stage = excluded.opportunity_stage, unanswered_messages = excluded.unanswered_messages, channel = excluded.channel, has_agreed_date = excluded.has_agreed_date, applies_4x4 = excluded.applies_4x4, recommended_stage = excluded.recommended_stage, stage_name = excluded.stage_name, interpretation = excluded.interpretation, objective = excluded.objective, suggested_action = excluded.suggested_action, advice = excluded.advice, mistake_to_avoid = excluded.mistake_to_avoid, empathetic_message = excluded.empathetic_message, neutral_message = excluded.neutral_message, direct_message = excluded.direct_message, related_lesson_ids = excluded.related_lesson_ids, active = excluded.active;

insert into public.objections (id, slug, title, category, common_phrase, is_open_ended, what_it_may_express, what_not_to_assume, questions_to_explore, what_to_avoid, next_goal, empathetic_response, neutral_response, direct_response, mistake_to_avoid, related_lesson_ids, keywords, active)
values ('obj-caro', 'es-muy-caro', 'Es muy caro', 'Precio', '"Es muy caro" / "Está por encima de lo que pensaba"', false, array['No percibe todavía el valor completo de la propuesta.', 'Lo está comparando con una opción de menor precio.', 'El monto total le genera impacto, aunque el valor por unidad de tiempo sea razonable.', 'Puede ser una forma cortés de decir que no es prioridad ahora.'], array['No asumas que no tiene el dinero: puede tratarse de percepción de valor, no de capacidad de pago.', 'No asumas que hay que bajar el precio de inmediato.', 'No asumas que está comparando con un competidor directo: puede estar comparando con no hacer nada.'], array['¿Con qué lo estás comparando?', '¿Qué parte de la propuesta te genera más dudas en relación con el valor?', 'Si el precio no fuera un tema, ¿avanzarías con la propuesta tal como está?'], array['Bajar el precio de forma automática, sin entender el motivo real.', 'Justificar el precio con una lista extensa de argumentos.', 'Compararte de forma negativa con la competencia.'], 'Entender si el freno es de percepción de valor, de prioridad o de presupuesto real, y ajustar la propuesta o la comunicación en consecuencia.', '{"template":"Hola {{nombre}}, entiendo perfectamente que el monto te genere dudas. Me gustaría entender mejor: ¿con qué lo estás comparando? Así puedo mostrarte {{recurso}} para que tengas más elementos antes de decidir sobre {{propuesta}}.","example":"Hola Martina, entiendo perfectamente que el monto te genere dudas. Me gustaría entender mejor: ¿con qué lo estás comparando? Así puedo mostrarte cómo se distribuye la inversión en el proceso para que tengas más elementos antes de decidir sobre la propuesta."}'::jsonb, '{"template":"Hola {{nombre}}, gracias por la sinceridad respecto al {{propuesta}}. Para entender mejor tu situación: ¿el tema es el monto total o la forma de pago? Cualquiera de las dos cosas la podemos revisar.","example":"Hola Martina, gracias por la sinceridad respecto a la propuesta. Para entender mejor tu situación: ¿el tema es el monto total o la forma de pago? Cualquiera de las dos cosas la podemos revisar."}'::jsonb, '{"template":"Hola {{nombre}}, te propongo algo simple: contame en una línea qué parte del precio te genera más dudas, y vemos juntos si hay una forma de ajustar {{propuesta}} a tu situación.","example":"Hola Martina, te propongo algo simple: contame en una línea qué parte del precio te genera más dudas, y vemos juntos si hay una forma de ajustar la propuesta a tu situación."}'::jsonb, 'Ofrecer un descuento antes de entender si el problema es realmente el precio.', array['m5-l2', 'm5-l6'], array['caro', 'precio', 'costo', 'presupuesto alto'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, common_phrase = excluded.common_phrase, is_open_ended = excluded.is_open_ended, what_it_may_express = excluded.what_it_may_express, what_not_to_assume = excluded.what_not_to_assume, questions_to_explore = excluded.questions_to_explore, what_to_avoid = excluded.what_to_avoid, next_goal = excluded.next_goal, empathetic_response = excluded.empathetic_response, neutral_response = excluded.neutral_response, direct_response = excluded.direct_response, mistake_to_avoid = excluded.mistake_to_avoid, related_lesson_ids = excluded.related_lesson_ids, keywords = excluded.keywords, active = excluded.active;

insert into public.objections (id, slug, title, category, common_phrase, is_open_ended, what_it_may_express, what_not_to_assume, questions_to_explore, what_to_avoid, next_goal, empathetic_response, neutral_response, direct_response, mistake_to_avoid, related_lesson_ids, keywords, active)
values ('obj-sin-presupuesto', 'no-tengo-presupuesto', 'No tengo presupuesto', 'Precio', '"No tengo presupuesto para esto ahora"', false, array['Puede haber una restricción real de presupuesto en este momento.', 'Puede ser una forma de decir que no es prioridad, sin dar más detalle.', 'Puede indicar que el presupuesto está asignado a otra necesidad.'], array['No asumas que jamás va a tener presupuesto.', 'No asumas que es una excusa: puede ser una limitación concreta y temporal.'], array['¿Es un tema de presupuesto para este momento puntual, o para el proyecto en general?', '¿Hay una fecha en la que el presupuesto podría liberarse?', '¿Sería de ayuda pensar una versión más acotada para empezar?'], array['Insistir con el mismo monto sin ofrecer alternativas.', 'Dar por cerrada la oportunidad sin preguntar por plazos.'], 'Definir si corresponde ajustar el alcance, esperar una fecha de presupuesto o pasar a nurturing.', '{"template":"Hola {{nombre}}, entiendo la situación con el presupuesto. Para no perder de vista esto: ¿hay un momento del año en el que se libere presupuesto para {{necesidad}}? Me gustaría poder acompañarte cuando sea el momento.","example":"Hola Diego, entiendo la situación con el presupuesto. Para no perder de vista esto: ¿hay un momento del año en el que se libere presupuesto para este tipo de proyectos? Me gustaría poder acompañarte cuando sea el momento."}'::jsonb, '{"template":"Hola {{nombre}}, gracias por contarme. ¿Te sirve que pensemos una versión más acotada de {{propuesta}} que se ajuste al presupuesto actual, o preferís que retomemos más adelante?","example":"Hola Diego, gracias por contarme. ¿Te sirve que pensemos una versión más acotada de la propuesta que se ajuste al presupuesto actual, o preferís que retomemos más adelante?"}'::jsonb, '{"template":"Hola {{nombre}}, sin problema. ¿Charlamos brevemente para ver si hay una forma de adaptar {{propuesta}} al presupuesto disponible, o preferís que te contacte en {{fecha}}?","example":"Hola Diego, sin problema. ¿Charlamos brevemente para ver si hay una forma de adaptar la propuesta al presupuesto disponible, o preferís que te contacte en dos meses?"}'::jsonb, 'Cerrar la conversación sin preguntar si el presupuesto podría liberarse más adelante.', array['m5-l6', 'm4-l10'], array['presupuesto', 'dinero', 'no puedo pagar'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, common_phrase = excluded.common_phrase, is_open_ended = excluded.is_open_ended, what_it_may_express = excluded.what_it_may_express, what_not_to_assume = excluded.what_not_to_assume, questions_to_explore = excluded.questions_to_explore, what_to_avoid = excluded.what_to_avoid, next_goal = excluded.next_goal, empathetic_response = excluded.empathetic_response, neutral_response = excluded.neutral_response, direct_response = excluded.direct_response, mistake_to_avoid = excluded.mistake_to_avoid, related_lesson_ids = excluded.related_lesson_ids, keywords = excluded.keywords, active = excluded.active;

insert into public.objections (id, slug, title, category, common_phrase, is_open_ended, what_it_may_express, what_not_to_assume, questions_to_explore, what_to_avoid, next_goal, empathetic_response, neutral_response, direct_response, mistake_to_avoid, related_lesson_ids, keywords, active)
values ('obj-pensarlo', 'necesito-pensarlo', 'Necesito pensarlo', 'Confianza / decisión', '"Necesito pensarlo" / "Déjame evaluarlo"', false, array['Puede haber una duda puntual que no se animó a mencionar.', 'Puede necesitar tiempo real para procesar la información.', 'Puede ser una forma cortés de cerrar la conversación sin decir que no.'], array['No asumas que ''pensarlo'' significa que no va a avanzar.', 'No asumas que sabés qué es lo que necesita pensar sin preguntar.'], array['¿Hay algo puntual que te gustaría pensar con más detalle?', '¿Qué información te ayudaría a decidir con más tranquilidad?', '¿Para cuándo te gustaría retomar la conversación?'], array['Presionar para obtener una respuesta inmediata.', 'Dejar la conversación sin fecha de retorno.'], 'Acordar una fecha concreta para retomar y, si es posible, identificar la duda específica que motiva la pausa.', '{"template":"Hola {{nombre}}, tiene todo el sentido tomarte el tiempo necesario. Si te sirve, contame qué es lo que más te gustaría pensar sobre {{propuesta}}: puedo ayudarte a tener más claridad antes de que decidas.","example":"Hola Sofía, tiene todo el sentido tomarte el tiempo necesario. Si te sirve, contame qué es lo que más te gustaría pensar sobre la propuesta: puedo ayudarte a tener más claridad antes de que decidas."}'::jsonb, '{"template":"Hola {{nombre}}, perfecto. Para organizarnos: ¿te parece que retomemos el {{fecha}}? Así lo tenemos presente los dos.","example":"Hola Sofía, perfecto. Para organizarnos: ¿te parece que retomemos el próximo lunes? Así lo tenemos presente los dos."}'::jsonb, '{"template":"Hola {{nombre}}, sin problema. ¿Me confirmás una fecha aproximada para retomar {{propuesta}} y así te contacto en ese momento?","example":"Hola Sofía, sin problema. ¿Me confirmás una fecha aproximada para retomar la propuesta y así te contacto en ese momento?"}'::jsonb, 'No preguntar por una fecha concreta y dejar la conversación completamente abierta.', array['m5-l6', 'm2-l3'], array['pensarlo', 'evaluar', 'decisión'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, common_phrase = excluded.common_phrase, is_open_ended = excluded.is_open_ended, what_it_may_express = excluded.what_it_may_express, what_not_to_assume = excluded.what_not_to_assume, questions_to_explore = excluded.questions_to_explore, what_to_avoid = excluded.what_to_avoid, next_goal = excluded.next_goal, empathetic_response = excluded.empathetic_response, neutral_response = excluded.neutral_response, direct_response = excluded.direct_response, mistake_to_avoid = excluded.mistake_to_avoid, related_lesson_ids = excluded.related_lesson_ids, keywords = excluded.keywords, active = excluded.active;

insert into public.objections (id, slug, title, category, common_phrase, is_open_ended, what_it_may_express, what_not_to_assume, questions_to_explore, what_to_avoid, next_goal, empathetic_response, neutral_response, direct_response, mistake_to_avoid, related_lesson_ids, keywords, active)
values ('obj-no-prioridad', 'ahora-no-es-prioridad', 'Ahora no es prioridad', 'Prioridad', '"Ahora no es prioridad" / "Tengo otras cosas encima"', false, array['Puede haber temas más urgentes ocupando su atención en este momento.', 'Puede no tener claro el impacto de postergar esta decisión.', 'Puede ser una forma de decir que el valor percibido todavía no supera el esfuerzo de ocuparse ahora.'], array['No asumas que nunca va a ser prioridad.', 'No asumas que insistir con urgencia va a cambiar su percepción.'], array['¿Qué tendría que pasar para que esto se vuelva prioridad?', '¿Hay una fecha en la que esto empiece a pesar más en tu agenda?', '¿Te sirve que te comparta información mientras tanto, sin presionarte a decidir ahora?'], array['Cuestionar sus prioridades o minimizarlas.', 'Insistir con la misma frecuencia como si fuera una oportunidad activa.'], 'Comprender el horizonte de tiempo real y pasar a un seguimiento espaciado si corresponde.', '{"template":"Hola {{nombre}}, entiendo que hoy tengas otras cosas encima. Me gustaría acompañarte igual: ¿te sirve que te escriba más adelante, o preferís que te comparta algo de valor mientras tanto sobre {{necesidad}}?","example":"Hola Julián, entiendo que hoy tengas otras cosas encima. Me gustaría acompañarte igual: ¿te sirve que te escriba más adelante, o preferís que te comparta algo de valor mientras tanto sobre la organización del equipo comercial?"}'::jsonb, '{"template":"Hola {{nombre}}, gracias por contarme. Para no interrumpirte sin sentido: ¿te parece que retomemos en {{fecha}}?","example":"Hola Julián, gracias por contarme. Para no interrumpirte sin sentido: ¿te parece que retomemos en un mes?"}'::jsonb, '{"template":"Hola {{nombre}}, entendido. ¿Te escribo en {{fecha}} para retomar, o preferís avisarme vos cuando sea buen momento?","example":"Hola Julián, entendido. ¿Te escribo en un mes para retomar, o preferís avisarme vos cuando sea buen momento?"}'::jsonb, 'Seguir escribiendo con la misma frecuencia que si la oportunidad estuviera activa.', array['m4-l10', 'm2-l4'], array['prioridad', 'no es momento', 'urgencia'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, common_phrase = excluded.common_phrase, is_open_ended = excluded.is_open_ended, what_it_may_express = excluded.what_it_may_express, what_not_to_assume = excluded.what_not_to_assume, questions_to_explore = excluded.questions_to_explore, what_to_avoid = excluded.what_to_avoid, next_goal = excluded.next_goal, empathetic_response = excluded.empathetic_response, neutral_response = excluded.neutral_response, direct_response = excluded.direct_response, mistake_to_avoid = excluded.mistake_to_avoid, related_lesson_ids = excluded.related_lesson_ids, keywords = excluded.keywords, active = excluded.active;

insert into public.objections (id, slug, title, category, common_phrase, is_open_ended, what_it_may_express, what_not_to_assume, questions_to_explore, what_to_avoid, next_goal, empathetic_response, neutral_response, direct_response, mistake_to_avoid, related_lesson_ids, keywords, active)
values ('obj-hablarlo-otra-persona', 'tengo-que-hablarlo-con-otra-persona', 'Tengo que hablarlo con otra persona', 'Autoridad / decisión', '"Lo tengo que hablar con mi socio / mi pareja / mi equipo"', false, array['La decisión efectivamente involucra a otra persona.', 'Puede necesitar más argumentos para poder trasladar la propuesta.', 'Puede ser una forma de tomarse tiempo sin comprometerse.'], array['No asumas que es una excusa: en muchos procesos la decisión es genuinamente compartida.', 'No asumas que la otra persona conoce el mismo nivel de detalle que tu interlocutor.'], array['¿Qué información le sería útil a esa persona para evaluarlo?', '¿Tendría sentido armar un resumen breve para compartir?', '¿Sería posible coordinar una conversación breve los tres, si eso ayuda a resolver dudas más rápido?'], array['Presionar para que decida sin consultar a esa persona.', 'Asumir que esa persona va a tener una objeción negativa sin evidencia.'], 'Facilitar la conversación con el tercero, aportando material claro y proponiendo un próximo paso con fecha.', '{"template":"Hola {{nombre}}, tiene todo el sentido que lo converses con {{tercero}}. Para ayudarte, te armo un resumen breve de {{propuesta}} que puedas compartir fácilmente. ¿Te sirve?","example":"Hola Camila, tiene todo el sentido que lo converses con tu socio. Para ayudarte, te armo un resumen breve de la propuesta que puedas compartir fácilmente. ¿Te sirve?"}'::jsonb, '{"template":"Hola {{nombre}}, entendido. ¿Te ayudaría un resumen de una página con los puntos clave de {{propuesta}} para compartir con {{tercero}}?","example":"Hola Camila, entendido. ¿Te ayudaría un resumen de una página con los puntos clave de la propuesta para compartir con tu socio?"}'::jsonb, '{"template":"Hola {{nombre}}, perfecto. Te paso un resumen breve para {{tercero}} y coordinamos una fecha para conversarlo juntos, ¿te sirve el {{fecha}}?","example":"Hola Camila, perfecto. Te paso un resumen breve para tu socio y coordinamos una fecha para conversarlo juntos, ¿te sirve el jueves?"}'::jsonb, 'No ofrecer material de apoyo y dejar que la persona explique la propuesta de memoria.', array['m5-l2'], array['tercero', 'socio', 'decisión compartida', 'autoridad'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, common_phrase = excluded.common_phrase, is_open_ended = excluded.is_open_ended, what_it_may_express = excluded.what_it_may_express, what_not_to_assume = excluded.what_not_to_assume, questions_to_explore = excluded.questions_to_explore, what_to_avoid = excluded.what_to_avoid, next_goal = excluded.next_goal, empathetic_response = excluded.empathetic_response, neutral_response = excluded.neutral_response, direct_response = excluded.direct_response, mistake_to_avoid = excluded.mistake_to_avoid, related_lesson_ids = excluded.related_lesson_ids, keywords = excluded.keywords, active = excluded.active;

insert into public.objections (id, slug, title, category, common_phrase, is_open_ended, what_it_may_express, what_not_to_assume, questions_to_explore, what_to_avoid, next_goal, empathetic_response, neutral_response, direct_response, mistake_to_avoid, related_lesson_ids, keywords, active)
values ('obj-mas-informacion', 'mandame-mas-informacion', 'Mandame más información', 'Información', '"Mandame más información" / "Pasame material para revisar"', false, array['Puede necesitar más detalles concretos antes de decidir.', 'Puede ser una forma cortés de posponer sin comprometerse a nada.', 'Puede querer compartir la información con otra persona.'], array['No asumas que un envío genérico de información resuelve la situación.', 'No asumas que pedir información significa interés firme: conviene calificarlo.'], array['¿Hay algo puntual sobre lo que te gustaría tener más detalle?', '¿La información es para vos o para compartir con alguien más?', 'Después de revisarla, ¿te sirve que coordinemos una fecha para conversar dudas?'], array['Enviar información genérica sin acordar un próximo paso posterior.', 'No preguntar qué información específica es útil.'], 'Enviar información relevante y acordar de antemano una fecha para retomar la conversación.', '{"template":"Hola {{nombre}}, con gusto. Te comparto {{recurso}} pensando en {{necesidad}}. Para que no quede sin cierre: ¿coordinamos una charla breve el {{fecha}} para resolver dudas después de que lo revises?","example":"Hola Nicolás, con gusto. Te comparto el material con casos similares al tuyo pensando en la necesidad de ordenar el equipo comercial. Para que no quede sin cierre: ¿coordinamos una charla breve el viernes para resolver dudas después de que lo revises?"}'::jsonb, '{"template":"Hola {{nombre}}, te comparto {{recurso}} sobre {{propuesta}}. Quedo atento a tus comentarios y, si te sirve, coordinamos una breve llamada el {{fecha}} para conversarlo.","example":"Hola Nicolás, te comparto el brochure sobre la propuesta. Quedo atento a tus comentarios y, si te sirve, coordinamos una breve llamada el lunes para conversarlo."}'::jsonb, '{"template":"Hola {{nombre}}, te dejo {{recurso}}. ¿Coordinamos ya una fecha para revisarlo juntos, el {{fecha}} por ejemplo?","example":"Hola Nicolás, te dejo el material. ¿Coordinamos ya una fecha para revisarlo juntos, el jueves por ejemplo?"}'::jsonb, 'Enviar la información y no proponer ningún próximo paso, dejando la conversación abierta.', array['m4-l6', 'm2-l3'], array['información', 'material', 'brochure'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, common_phrase = excluded.common_phrase, is_open_ended = excluded.is_open_ended, what_it_may_express = excluded.what_it_may_express, what_not_to_assume = excluded.what_not_to_assume, questions_to_explore = excluded.questions_to_explore, what_to_avoid = excluded.what_to_avoid, next_goal = excluded.next_goal, empathetic_response = excluded.empathetic_response, neutral_response = excluded.neutral_response, direct_response = excluded.direct_response, mistake_to_avoid = excluded.mistake_to_avoid, related_lesson_ids = excluded.related_lesson_ids, keywords = excluded.keywords, active = excluded.active;

insert into public.objections (id, slug, title, category, common_phrase, is_open_ended, what_it_may_express, what_not_to_assume, questions_to_explore, what_to_avoid, next_goal, empathetic_response, neutral_response, direct_response, mistake_to_avoid, related_lesson_ids, keywords, active)
values ('obj-otro-proveedor', 'ya-trabajo-con-otro-proveedor', 'Ya trabajo con otro proveedor', 'Competencia', '"Ya trabajo con otro proveedor / otra persona para esto"', false, array['Puede estar conforme con la relación actual.', 'Puede haber una necesidad puntual que el proveedor actual no cubre del todo.', 'Puede ser una forma de cerrar la conversación sin dar más detalle.'], array['No asumas que está eligiendo a la competencia por sobre vos.', 'No asumas que no vale la pena seguir la conversación.'], array['¿Qué es lo que más valorás de esa relación actual?', '¿Hay algo que te gustaría que funcionara distinto?', '¿Tendría sentido que quedemos en contacto para el futuro, por si la situación cambia?'], array['Hablar mal del proveedor actual.', 'Insistir para que cambie de proveedor sin entender su situación.'], 'Dejar una puerta abierta clara para el futuro, sin presionar por un cambio inmediato.', '{"template":"Hola {{nombre}}, me alegra que tengas una solución que te funciona. Si en algún momento surge algo puntual donde pueda sumar valor con {{servicio}}, quedo a disposición. ¿Te parece que sigamos en contacto?","example":"Hola Rocío, me alegra que tengas una solución que te funciona. Si en algún momento surge algo puntual donde pueda sumar valor con la propuesta de comunicación, quedo a disposición. ¿Te parece que sigamos en contacto?"}'::jsonb, '{"template":"Hola {{nombre}}, entendido, gracias por contarme. ¿Te parece si quedamos en contacto para el futuro, por si en algún momento necesitás una segunda opción para {{necesidad}}?","example":"Hola Rocío, entendido, gracias por contarme. ¿Te parece si quedamos en contacto para el futuro, por si en algún momento necesitás una segunda opción para este tipo de proyectos?"}'::jsonb, '{"template":"Hola {{nombre}}, gracias por la claridad. Te dejo mi contacto por si en el futuro necesitás algo puntual relacionado con {{servicio}}.","example":"Hola Rocío, gracias por la claridad. Te dejo mi contacto por si en el futuro necesitás algo puntual relacionado con este servicio."}'::jsonb, 'Comparar negativamente al proveedor actual para intentar generar duda.', array['m4-l10'], array['competencia', 'proveedor', 'ya tengo'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, common_phrase = excluded.common_phrase, is_open_ended = excluded.is_open_ended, what_it_may_express = excluded.what_it_may_express, what_not_to_assume = excluded.what_not_to_assume, questions_to_explore = excluded.questions_to_explore, what_to_avoid = excluded.what_to_avoid, next_goal = excluded.next_goal, empathetic_response = excluded.empathetic_response, neutral_response = excluded.neutral_response, direct_response = excluded.direct_response, mistake_to_avoid = excluded.mistake_to_avoid, related_lesson_ids = excluded.related_lesson_ids, keywords = excluded.keywords, active = excluded.active;

insert into public.objections (id, slug, title, category, common_phrase, is_open_ended, what_it_may_express, what_not_to_assume, questions_to_explore, what_to_avoid, next_goal, empathetic_response, neutral_response, direct_response, mistake_to_avoid, related_lesson_ids, keywords, active)
values ('obj-no-tiempo', 'no-tengo-tiempo', 'No tengo tiempo', 'Prioridad', '"No tengo tiempo para esto ahora"', false, array['Puede haber una carga de trabajo real que impide ocuparse ahora.', 'Puede no percibir el tiempo que realmente demandaría avanzar.', 'Puede ser una forma de decir que todavía no es prioridad.'], array['No asumas que nunca va a tener tiempo.', 'No asumas que avanzar requiere más tiempo del que realmente implica.'], array['¿Cuánto tiempo estimás que necesitarías para poder evaluarlo con tranquilidad?', '¿Hay un momento del mes en el que tengas más disponibilidad?', '¿Te sirve si simplifico la propuesta para que requiera menos tiempo de tu parte?'], array['Restarle importancia a su falta de tiempo.', 'Proponer reuniones largas cuando lo que falta es justamente tiempo.'], 'Reducir el esfuerzo requerido para avanzar y acordar una fecha realista.', '{"template":"Hola {{nombre}}, entiendo, el tiempo es un recurso escaso. ¿Te sirve si lo resolvemos en una llamada breve de 10 minutos, o preferís que te contacte en {{fecha}}?","example":"Hola Tomás, entiendo, el tiempo es un recurso escaso. ¿Te sirve si lo resolvemos en una llamada breve de 10 minutos, o preferís que te contacte la semana que viene?"}'::jsonb, '{"template":"Hola {{nombre}}, entendido. ¿Preferís que avancemos con algo breve por escrito o coordinamos una fecha en la que tengas más disponibilidad?","example":"Hola Tomás, entendido. ¿Preferís que avancemos con algo breve por escrito o coordinamos una fecha en la que tengas más disponibilidad?"}'::jsonb, '{"template":"Hola {{nombre}}, sin problema. ¿Me decís qué día de {{fecha}} te queda mejor y lo resolvemos rápido?","example":"Hola Tomás, sin problema. ¿Me decís qué día de la próxima semana te queda mejor y lo resolvemos rápido?"}'::jsonb, 'Proponer una reunión larga cuando el problema declarado es, justamente, la falta de tiempo.', array['m2-l3'], array['tiempo', 'agenda', 'ocupado'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, common_phrase = excluded.common_phrase, is_open_ended = excluded.is_open_ended, what_it_may_express = excluded.what_it_may_express, what_not_to_assume = excluded.what_not_to_assume, questions_to_explore = excluded.questions_to_explore, what_to_avoid = excluded.what_to_avoid, next_goal = excluded.next_goal, empathetic_response = excluded.empathetic_response, neutral_response = excluded.neutral_response, direct_response = excluded.direct_response, mistake_to_avoid = excluded.mistake_to_avoid, related_lesson_ids = excluded.related_lesson_ids, keywords = excluded.keywords, active = excluded.active;

insert into public.objections (id, slug, title, category, common_phrase, is_open_ended, what_it_may_express, what_not_to_assume, questions_to_explore, what_to_avoid, next_goal, empathetic_response, neutral_response, direct_response, mistake_to_avoid, related_lesson_ids, keywords, active)
values ('obj-mas-adelante', 'hablemos-mas-adelante', 'Hablemos más adelante', 'Prioridad / tiempos', '"Hablemos más adelante" / "Te escribo yo cuando sea el momento"', false, array['Puede haber un motivo concreto por el que el momento actual no es el indicado.', 'Puede ser una forma amable de cerrar la conversación por ahora.'], array['No asumas una fecha: preguntala explícitamente.', 'No asumas que ''más adelante'' significa que no hay interés.'], array['¿Hay un momento aproximado en el que te gustaría retomar?', '¿Qué tendría que cambiar para que sea un buen momento?'], array['Dejar pasar el tema sin acordar ninguna fecha de referencia.', 'Escribir antes del plazo que la persona mencionó.'], 'Acordar una fecha aproximada de recontacto y pasar a nurturing si no hay fecha concreta.', '{"template":"Hola {{nombre}}, por supuesto. Para tenerlo presente sin molestarte antes de tiempo: ¿te sirve que retomemos en {{fecha}}?","example":"Hola Valentina, por supuesto. Para tenerlo presente sin molestarte antes de tiempo: ¿te sirve que retomemos en dos meses?"}'::jsonb, '{"template":"Hola {{nombre}}, entendido. Quedo en contacto para {{fecha}}, salvo que prefieras escribirme vos cuando sea el momento.","example":"Hola Valentina, entendido. Quedo en contacto para fin de año, salvo que prefieras escribirme vos cuando sea el momento."}'::jsonb, '{"template":"Hola {{nombre}}, perfecto. Te contacto en {{fecha}}. Si antes surge algo, quedo disponible.","example":"Hola Valentina, perfecto. Te contacto en marzo. Si antes surge algo, quedo disponible."}'::jsonb, 'Volver a escribir antes de la fecha acordada, sin un motivo nuevo y relevante.', array['m4-l10', 'm4-l9'], array['más adelante', 'después', 'nurturing'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, common_phrase = excluded.common_phrase, is_open_ended = excluded.is_open_ended, what_it_may_express = excluded.what_it_may_express, what_not_to_assume = excluded.what_not_to_assume, questions_to_explore = excluded.questions_to_explore, what_to_avoid = excluded.what_to_avoid, next_goal = excluded.next_goal, empathetic_response = excluded.empathetic_response, neutral_response = excluded.neutral_response, direct_response = excluded.direct_response, mistake_to_avoid = excluded.mistake_to_avoid, related_lesson_ids = excluded.related_lesson_ids, keywords = excluded.keywords, active = excluded.active;

insert into public.objections (id, slug, title, category, common_phrase, is_open_ended, what_it_may_express, what_not_to_assume, questions_to_explore, what_to_avoid, next_goal, empathetic_response, neutral_response, direct_response, mistake_to_avoid, related_lesson_ids, keywords, active)
values ('obj-no-es-para-mi', 'no-estoy-seguro-de-que-sea-para-mi', 'No estoy seguro de que sea para mí', 'Confianza / encaje', '"No sé si esto es realmente para mí"', false, array['Puede tener dudas genuinas sobre si el servicio se ajusta a su situación particular.', 'Puede no haber entendido completamente el alcance de la propuesta.', 'Puede estar comparando con su propia idea de lo que necesita.'], array['No asumas que no encaja: preguntá qué le genera la duda puntualmente.', 'No asumas que necesita el mismo servicio que otros clientes.'], array['¿Qué parte específica te genera esa duda?', '¿Cómo te imaginás que debería ser la solución ideal para tu situación?', '¿Te sirve que revisemos juntos si el alcance actual se ajusta a lo que necesitás?'], array['Insistir en que sí encaja sin entender la duda concreta.', 'Minimizar su preocupación.'], 'Aclarar el encaje real y ajustar la propuesta si corresponde, o reconocer honestamente si no es el mejor fit.', '{"template":"Hola {{nombre}}, gracias por decírmelo con honestidad. Contame un poco más: ¿qué es lo que te genera esa duda sobre {{propuesta}}? Así vemos juntos si realmente se ajusta a {{necesidad}}.","example":"Hola Agustina, gracias por decírmelo con honestidad. Contame un poco más: ¿qué es lo que te genera esa duda sobre la propuesta? Así vemos juntos si realmente se ajusta a lo que estás buscando."}'::jsonb, '{"template":"Hola {{nombre}}, entiendo la duda. ¿Te parece si repasamos juntos los puntos de {{propuesta}} para confirmar si se ajusta bien a {{necesidad}}?","example":"Hola Agustina, entiendo la duda. ¿Te parece si repasamos juntos los puntos de la propuesta para confirmar si se ajusta bien a lo que estás buscando?"}'::jsonb, '{"template":"Hola {{nombre}}, te propongo algo concreto: contame qué parte te genera dudas y te digo con sinceridad si es o no un buen fit.","example":"Hola Agustina, te propongo algo concreto: contame qué parte te genera dudas y te digo con sinceridad si es o no un buen fit."}'::jsonb, 'Convencer a toda costa en lugar de evaluar honestamente si hay un buen encaje.', array['m5-l6'], array['encaje', 'confianza', 'dudas'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, common_phrase = excluded.common_phrase, is_open_ended = excluded.is_open_ended, what_it_may_express = excluded.what_it_may_express, what_not_to_assume = excluded.what_not_to_assume, questions_to_explore = excluded.questions_to_explore, what_to_avoid = excluded.what_to_avoid, next_goal = excluded.next_goal, empathetic_response = excluded.empathetic_response, neutral_response = excluded.neutral_response, direct_response = excluded.direct_response, mistake_to_avoid = excluded.mistake_to_avoid, related_lesson_ids = excluded.related_lesson_ids, keywords = excluded.keywords, active = excluded.active;

insert into public.objections (id, slug, title, category, common_phrase, is_open_ended, what_it_may_express, what_not_to_assume, questions_to_explore, what_to_avoid, next_goal, empathetic_response, neutral_response, direct_response, mistake_to_avoid, related_lesson_ids, keywords, active)
values ('obj-no-se-ajusta', 'la-propuesta-no-se-ajusta', 'La propuesta no se ajusta a lo que necesito', 'Encaje / alcance', '"Esto no es exactamente lo que estaba buscando"', false, array['Puede haber un desajuste real entre el alcance propuesto y la necesidad.', 'Puede haber un malentendido sobre lo que incluye la propuesta.', 'Puede estar comparando con una expectativa que no se comunicó antes.'], array['No asumas que sabés en qué falla la propuesta sin preguntar.', 'No asumas que hay que rehacer todo desde cero.'], array['¿Qué parte específica sentís que no se ajusta?', '¿Cómo te imaginabas la solución antes de recibir la propuesta?', '¿Qué tendría que cambiar para que se ajuste mejor?'], array['Ponerse a la defensiva sobre el trabajo ya realizado.', 'Ignorar el comentario y reenviar la misma propuesta.'], 'Identificar el punto exacto de desajuste y ofrecer una versión ajustada o una aclaración específica.', '{"template":"Hola {{nombre}}, gracias por decírmelo. Quiero entender bien: ¿qué parte de {{propuesta}} sentís que no se ajusta a {{necesidad}}? Así la ajustamos juntos.","example":"Hola Ezequiel, gracias por decírmelo. Quiero entender bien: ¿qué parte de la propuesta sentís que no se ajusta a lo que necesitás? Así la ajustamos juntos."}'::jsonb, '{"template":"Hola {{nombre}}, entendido. ¿Podés contarme puntualmente qué parte no encaja, para revisar {{propuesta}} y ajustarla?","example":"Hola Ezequiel, entendido. ¿Podés contarme puntualmente qué parte no encaja, para revisar la propuesta y ajustarla?"}'::jsonb, '{"template":"Hola {{nombre}}, decime concretamente qué cambiarías de {{propuesta}} y te mando una versión ajustada.","example":"Hola Ezequiel, decime concretamente qué cambiarías de la propuesta y te mando una versión ajustada."}'::jsonb, 'Reenviar la misma propuesta sin cambios, esperando una respuesta distinta.', array['m2-l3', 'm5-l6'], array['ajuste', 'alcance', 'propuesta'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, common_phrase = excluded.common_phrase, is_open_ended = excluded.is_open_ended, what_it_may_express = excluded.what_it_may_express, what_not_to_assume = excluded.what_not_to_assume, questions_to_explore = excluded.questions_to_explore, what_to_avoid = excluded.what_to_avoid, next_goal = excluded.next_goal, empathetic_response = excluded.empathetic_response, neutral_response = excluded.neutral_response, direct_response = excluded.direct_response, mistake_to_avoid = excluded.mistake_to_avoid, related_lesson_ids = excluded.related_lesson_ids, keywords = excluded.keywords, active = excluded.active;

insert into public.objections (id, slug, title, category, common_phrase, is_open_ended, what_it_may_express, what_not_to_assume, questions_to_explore, what_to_avoid, next_goal, empathetic_response, neutral_response, direct_response, mistake_to_avoid, related_lesson_ids, keywords, active)
values ('obj-otra', 'otra-objecion', 'Otra objeción', 'General', 'Una objeción que no aparece en la lista.', true, array['Puede tratarse de precio, prioridad, confianza, tiempo, autoridad o necesidad, aunque no se haya dicho explícitamente.'], array['No asumas de qué se trata sin que la persona amplíe la idea.'], array['¿Podés contarme un poco más sobre lo que te genera dudas?', '¿Qué aspecto puntual te preocupa más?', '¿Se relaciona más con el precio, el momento, la confianza o la necesidad?'], array['Responder antes de comprender la objeción real.', 'Dar una respuesta genérica sin haber indagado.'], 'Comprender la categoría real de la objeción (precio, prioridad, confianza, tiempo, autoridad o necesidad) antes de responder.', '{"template":"Hola {{nombre}}, quiero entender bien tu situación antes de responder. ¿Podés contarme un poco más sobre lo que te genera dudas respecto a {{propuesta}}?","example":"Hola, quiero entender bien tu situación antes de responder. ¿Podés contarme un poco más sobre lo que te genera dudas respecto a la propuesta?"}'::jsonb, '{"template":"Hola {{nombre}}, para poder ayudarte mejor: ¿qué aspecto puntual te preocupa más en este momento?","example":"Hola, para poder ayudarte mejor: ¿qué aspecto puntual te preocupa más en este momento?"}'::jsonb, '{"template":"Hola {{nombre}}, contame en pocas palabras qué te frena y vemos juntos cómo resolverlo.","example":"Hola, contame en pocas palabras qué te frena y vemos juntos cómo resolverlo."}'::jsonb, 'Interpretar libremente la objeción sin haber preguntado.', array['m5-l1', 'm5-l4'], array['otra', 'general', 'no listada'], true)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, common_phrase = excluded.common_phrase, is_open_ended = excluded.is_open_ended, what_it_may_express = excluded.what_it_may_express, what_not_to_assume = excluded.what_not_to_assume, questions_to_explore = excluded.questions_to_explore, what_to_avoid = excluded.what_to_avoid, next_goal = excluded.next_goal, empathetic_response = excluded.empathetic_response, neutral_response = excluded.neutral_response, direct_response = excluded.direct_response, mistake_to_avoid = excluded.mistake_to_avoid, related_lesson_ids = excluded.related_lesson_ids, keywords = excluded.keywords, active = excluded.active;

